window.READING_AIDS={"hanja": {"甲": null, "乙": null, "丙": null, "丁": null, "戊": null, "解說": null, "判": null, "子": "자", "死傷": "사상", "告知": "고지", "過失": "과실", "通": null, "通說": "통설", "前": "전", "共同說": "공동설", "準": "준", "事業運": "사업운", "出捐": "출연", "舊": "구", "容態": "용태", "不法行爲": "불법행위", "程度": "정도", "危險源": "위험원", "不作爲": "부작위", "抽象的": "추상적", "具體的": "구체적", "中間責任": "중간책임", "眞太陽時": "진태양시", "上下": "상하", "相當因果關係說": "상당인과관계설", "自然人": "자연인", "法人": "법인", "人": "인", "死者": "사자", "差額說": "차액설", "債務者": "채무자", "注意義務": "주의의무", "法益": "법익", "目的": "목적", "公路": "공로", "說": null, "性的": "성적", "寬解": "관해", "妻": "처", "多": null, "代位": "대위", "外觀": "외관", "信義則": "신의칙", "瑕疵": "하자", "共同": "공동", "主觀的": "주관적", "客觀的": "객관적", "判例": "판례", "敎唆": "교사", "幇助": "방조", "連帶": "연대", "醫療過誤": "의료과오", "醫療過誤責任": "의료과오책임", "不注意": "부주의", "父": "부", "侵襲": "침습", "濫獲": "남획", "表土": "표토", "坑水": "갱수", "鑛煙": "광연", "讓受": "양수", "新車": "신차", "舊車": "구차", "借主": "차주", "代替設計": "대체설계", "業": "업", "識別": "식별", "誤認": "오인", "免": "면", "特約": "특약", "潛伏期間": "잠복기간", "起算": "기산", "民": null, "法": null}, "precedents": {"민법4_강의자료(사무관리, 부당이득)-4": [{"key": "1", "start": 0, "end": 2, "citation": "대법원 2010. 1. 14. 선고 2007다55477 판결", "summary": "약정된 의무를 모두 이행한 뒤 새 계약을 기대하며 타인의 사무를 처리한 경우에도 사무관리가 성립할 수 있다. 직업·영업의 범위에서 제공한 용역은 통상의 보수 상당액을 필요비·유익비로 청구할 수 있다.", "pages": [4, 5], "sourceHash": "6e9f2bc89d779823a54f4805aa942265a7adc024f8e531b43215669eaea13787"}], "민법4_강의자료(사무관리, 부당이득)-5": [{"key": "2", "start": 0, "end": 1, "citation": "대법원 2010. 6. 10. 선고 2009다98669 판결", "summary": "종전 조합과의 계약이 새 조합에 승계됐다고 생각하거나 새 계약을 기대하며 새 조합의 업무를 처리한 경우, 새 조합과의 사무관리 관계가 인정될 수 있다.", "pages": [5], "sourceHash": "9b50f2a32e2cb46ae5777505d3df71625025ed96bb5c5b98e3e50b23649c5479"}], "민법4_강의자료(사무관리, 부당이득)-7": [{"key": "3", "start": 0, "end": 1, "citation": "대법원 1997. 10. 10. 선고 97다26326 판결", "summary": "사무관리는 타인의 사무를 그 사람을 위해 처리하려는 의사가 있고, 그 처리가 본인에게 불리하거나 본인의 의사에 반함이 명백하지 않아야 성립한다.", "pages": [7], "sourceHash": "492f2523858278afdc523cc1e97fd5a0622e31f31fdc074e05479a72f10964ed"}], "민법4_강의자료(사무관리, 부당이득)-10": [{"key": "4", "start": 0, "end": 1, "citation": "대법원 1995. 9. 15. 선고 94다59943 판결", "summary": "처리한 일이 타인의 사무가 아니거나 타인을 위한 관리의사가 없으면 사무관리가 성립하지 않는다.", "pages": [8], "sourceHash": "82d287bbde78fd826a13c3a563fd85369c98df0d7424e6f673491dda19174197"}], "민법4_강의자료(사무관리, 부당이득)-11": [{"key": "5", "start": 0, "end": 1, "citation": "대법원 2013. 8. 22. 선고 2013다30882 판결", "summary": "타인을 위한 관리의사는 자기 이익을 위한 의사와 함께 존재할 수 있다. 외부에 표시되거나 관리 당시 확정돼 있을 필요도 없다.", "pages": [9], "sourceHash": "c761492cb12e9cf62ed9cafe892ea206e033f9d0a8f0e5892002860cc0b82df2"}], "민법4_강의자료(사무관리, 부당이득)-13": [{"key": "6", "start": 0, "end": 4, "citation": "대법원 1995. 5. 12. 선고 94다25551 판결", "summary": "부당이득 반환액에서는 취득비용과 수익자의 독자적 노력으로 얻은 운용이익을 공제한다. 조부모 묘가 있는 임야를 심하게 훼손한 경우에는 재산상 배상만으로 회복되지 않는 정신적 손해의 위자료도 인정될 수 있다.", "pages": [9], "sourceHash": "87f4de11bf2ae14b95aa5d5e8da67eb26e9140762c34db0eb952fedeabd9c7ee"}], "민법4_강의자료(사무관리, 부당이득)-14": [{"key": "7", "start": 0, "end": 1, "citation": "대법원 2013. 9. 26. 선고 2012다43539 판결", "summary": "제3자와의 약정상 의무를 이행하며 타인의 사무를 처리한 경우, 원칙적으로 그 타인과의 관계에서 사무관리는 성립하지 않는다.", "pages": [10], "sourceHash": "a1f164bca156ccce1192e0644bb7a3b0ecdac068b45608f08a4c6413800cde54"}], "민법4_강의자료(사무관리, 부당이득)-15": [{"key": "8", "start": 0, "end": 1, "citation": "대법원 2013. 8. 22. 선고 2013다30882 판결", "summary": "타인을 위한 관리의사는 자기 이익을 위한 의사와 함께 존재할 수 있다. 외부에 표시되거나 관리 당시 확정돼 있을 필요도 없다.", "pages": [10], "sourceHash": "c761492cb12e9cf62ed9cafe892ea206e033f9d0a8f0e5892002860cc0b82df2"}], "민법4_강의자료(사무관리, 부당이득)-16": [{"key": "9", "start": 0, "end": 1, "citation": "대법원 1975. 4. 8. 선고 75다254 판결", "summary": "본인이 직접 관리하겠다는 의사를 외부에 명백하게 나타내면, 별도로 종료를 통지하지 않아도 사무관리는 더 이상 성립할 수 없다.", "pages": [11], "sourceHash": "13bd5507936a1d1560e0ee2ffdfb5c7bbff5c1e2a96c08b202e067d08f74f205"}], "민법4_강의자료(사무관리, 부당이득)-17": [{"key": "10", "start": 0, "end": 1, "citation": "대법원 2010. 1. 14. 선고 2007다55477 판결", "summary": "주로 보수를 받아 자기 이익을 얻으려는 사무관리에서는 본인의 이익·의사에 부합하는지 등 성립요건을 더욱 엄격하고 신중하게 판단해야 한다.", "pages": [11], "sourceHash": "b9c7e098296495e028aa02e83c68704988d501b4112a532e4224a5fb0506ba2e"}], "민법4_강의자료(사무관리, 부당이득)-26": [{"key": "11", "start": 0, "end": 1, "citation": "대법원 1995. 9. 29. 선고 94다13008 판결", "summary": "다른 사람을 대신해 가스레인지를 켜 사무관리를 시작했다면, 필요가 없어졌을 때 불을 끄는 등 적절히 관리해야 한다. 이를 게을리해 화재가 나면 손해배상책임을 진다.", "pages": [14], "sourceHash": "6e0ad48bb8421ca68937334425de2bf41c7d3b9fb63c3e074848c1f49d1749df"}], "민법4_강의자료(사무관리, 부당이득)-36": [{"key": "12", "start": 0, "end": 2, "citation": "대법원 2010. 1. 14. 선고 2007다55477 판결", "summary": "새 계약을 기대하며 법적 의무 없이 제공한 직업상 용역도 사무관리가 될 수 있다. 이때 통상의 보수 상당액을 필요비·유익비로 청구할 수 있다.", "pages": [17, 18], "sourceHash": "6e9f2bc89d779823a54f4805aa942265a7adc024f8e531b43215669eaea13787"}], "민법4_강의자료(사무관리, 부당이득)-39": [{"key": "13", "start": 0, "end": 1, "citation": "대법원 1995. 5. 12. 선고 94다25551 판결", "summary": "부당이득의 가액반환에서는 이득 취득에 든 비용과 수익자의 독자적 노력으로 생긴 운용이익을 공제한다. 손실자가 당연히 얻었을 이익까지 공제되는 것은 아니다.", "pages": [21], "sourceHash": "191305290235aa126bfef310392eda0a32ffd6877463f94d08df2f0cd2bd88e7"}], "민법4_강의자료(사무관리, 부당이득)-43": [{"key": "14", "start": 0, "end": 1, "citation": "대법원 1979. 11. 13. 선고 79다483 전원합의체 판결", "summary": "불법원인급여의 반환을 제한하는 것은 사회질서에 반하는 행위에 법적 보호를 주지 않기 위해서다. 이 사건에서는 내연관계의 대가로 이전한 부동산의 소유권이 수령자에게 귀속된다고 보았다.", "pages": [23], "sourceHash": "b321b52b402b0c31754fbc1043914000565f638e5a6be3c045e08f93b3c2d070"}], "민법4_강의자료(사무관리, 부당이득)-44": [{"key": "15", "start": 0, "end": 2, "citation": "대법원 2011. 06. 10. 선고 2010다40239 판결", "summary": "선의의 제3자 보호로 권리를 잃은 원권리자는 무권리자가 받은 처분대가를 침해부당이득으로 청구할 수 있다. 무권리자 자신의 처분으로 생긴 양도소득세 등은 반환액에서 공제하지 않는다.", "pages": [24], "sourceHash": "af07b37ed270f536f1351d846d74bbb87ac7af250b4f5a1a44af83901071e022"}], "민법4_강의자료(사무관리, 부당이득)-45": [{"key": "16", "start": 0, "end": 1, "citation": "대법원 1993. 4. 27. 선고 92다56087 판결", "summary": "사기에 의한 법률행위가 취소되고 동시에 불법행위도 성립하면, 부당이득반환청구와 손해배상청구는 병존한다. 어느 것을 선택할 수 있지만 이중으로 만족을 얻을 수는 없다.", "pages": [26], "sourceHash": "7ebe1d11e975d4b8487742817d4f011f3717b92883acc080665db12c65008cf9"}], "민법4_강의자료(사무관리, 부당이득)-46": [{"key": "17", "start": 0, "end": 1, "citation": "대법원 2013. 9. 13. 선고 2013다45457 판결", "summary": "부당이득반환청구와 손해배상청구는 별개이므로, 한 청구에서 승소했어도 만족을 얻지 못했다면 다른 청구의 이행판결을 구할 수 있다. 손해배상액이 책임제한 등으로 줄었다는 이유만으로 나머지 부당이득청구가 막히지는 않는다.", "pages": [26], "sourceHash": "a77f72bc6ffcbcf4b95b48630a02a0bcde69f1308b5d0afd5bccdc009d4da94e"}], "민법4_강의자료(사무관리, 부당이득)-49": [{"key": "18", "start": 0, "end": 1, "citation": "대법원 2005. 8. 25. 선고 2005다14595 판결", "summary": "적법한 배당요구를 하지 않아 배당에서 제외된 채권자는, 그 돈을 받은 후순위 채권자에게 부당이득반환을 청구할 수 없다.", "pages": [28], "sourceHash": "496473721ab6d080168aca8336f0e5c78159023ac781a57665512c7c3dfff997"}], "민법4_강의자료(사무관리, 부당이득)-50": [{"key": "19", "start": 0, "end": 1, "citation": "대법원 2016. 1. 14. 선고 2015다219733 판결", "summary": "장애인 차량 할인지원이 사업의 예정 범위를 일부 넘었더라도 법령의 복지지원 목적 안에 있다면, 공평과 정의에 비추어 곧바로 부당이득이라고 볼 수 없다.", "pages": [28], "sourceHash": "2352fa16d46eb3fa5caa17de68b5bcb1a457dff42f686df1c4793848e6fe19de"}], "민법4_강의자료(사무관리, 부당이득)-51": [{"key": "20", "start": 0, "end": 1, "citation": "대법원 2016. 1. 14. 선고 2015다218075 판결", "summary": "장애인 사망이나 세대 분리 등으로 지원 자격을 잃은 뒤 받은 차량 할인지원금은 법률상 원인이 없으므로 반환해야 한다.", "pages": [28], "sourceHash": "7bababbb1b36540309ddc660d5cd619b21c2a4355d152cca4943d7d59907487e"}], "민법4_강의자료(사무관리, 부당이득)-52": [{"key": "21", "start": 0, "end": 2, "citation": "대법원 2015. 6. 25. 선고 2014다5531 전원합의체 판결", "summary": "다수의견은 국립대학 기성회비를 실질적인 대학 이용의 대가로 보아 부당이득반환을 부정했다. 수록된 반대의견은 기성회의 징수에 법률상 근거가 없다는 점을 지적한다.", "pages": [29], "sourceHash": "534e64f55f8b0e76b1750342c4a1098f7895e8cc98f842d5467d4c9d84cb0e2b"}], "민법4_강의자료(사무관리, 부당이득)-55": [{"key": "22", "start": 0, "end": 2, "citation": "대법원 1991. 2. 26. 선고 90다6576 판결", "summary": "확정판결이 취소되지 않은 이상, 다른 소송에서 반대되는 판결이 나왔다는 사정만으로 그 집행이 불법행위가 되거나 집행으로 받은 돈이 부당이득이 되지는 않는다.", "pages": [30], "sourceHash": "4fc097495733db1cd746b4661b2e86e2b1f1ebcaeada1b200847d2a551e21730"}], "민법4_강의자료(사무관리, 부당이득)-56": [{"key": "23", "start": 0, "end": 1, "citation": "대법원 1988. 11. 8. 선고 86다카2949 판결", "summary": "배당표의 확정은 실체법상 권리까지 확정하지 않는다. 배당받아야 할 우선채권자가 잘못 배당받은 자에게 부당이득반환을 청구할 수 있다.", "pages": [30], "sourceHash": "9fb3facdfb0bfad2a3cd85da7a428cf04943bab99dcf2ae98cd61a6efe4439da"}], "민법4_강의자료(사무관리, 부당이득)-57": [{"key": "24", "start": 0, "end": 2, "citation": "대법원 2022. 12. 29. 선고 2019다272275 판결", "summary": "무권리자가 타인의 부동산을 팔아 받은 대금은 원소유자에 대한 부당이득이 되지 않는다. 매수인이 등기부취득시효로 소유권을 얻어도 원소유자의 손실과 매도대금 사이의 인과관계는 인정되지 않는다.", "pages": [31], "sourceHash": "14c436f05675eb9e3f67def046af178ba763c57dad44c1c29aee2c98780a0ef3"}], "민법4_강의자료(사무관리, 부당이득)-60": [{"key": "25", "start": 0, "end": 3, "citation": "대법원 1991. 10. 8. 선고 91다22018, 22025 판결", "summary": "타인의 차량을 점유했어도 실제로 사용·수익하지 않았다면 부당이득이 성립하지 않는다. 등록말소로 소유자도 운행수익을 얻을 수 없었다면 그에 대응하는 임대료 손실도 인정하기 어렵다.", "pages": [32], "sourceHash": "0982dc64253b922552418335ab0b7414e4874394ff44662676702351f125de02"}], "민법4_강의자료(사무관리, 부당이득)-61": [{"key": "26", "start": 0, "end": 2, "citation": "대법원 1984. 5. 15. 선고 84다카108 판결", "summary": "건물을 계속 점유했더라도 실제로 사용·수익하지 못했다면 차임 상당의 부당이득을 얻었다고 볼 수 없다.", "pages": [32, 33], "sourceHash": "108f23ce702588fd3c79f9e64f6eb8d060cc7ebe8ae06692fa66a3e4e677edcc"}], "민법4_강의자료(사무관리, 부당이득)-62": [{"key": "27", "start": 0, "end": 1, "citation": "대법원 1998. 7. 10. 선고 98다8554 판결", "summary": "임대차 종료 후 건물을 점유했어도 본래 용도로 사용·수익하지 않아 실질적 이익이 없었다면 부당이득반환의무가 없다. 임차인 자신의 사정으로 이용하지 못한 경우도 같다.", "pages": [33], "sourceHash": "af63c033672d512c28b07d266ff0dfbbaa577ad7a59094af25de00b47ad573d3"}], "민법4_강의자료(사무관리, 부당이득)-63": [{"key": "28", "start": 0, "end": 1, "citation": "대법원 1997. 12. 9. 선고, 96다47586 판결", "summary": "호텔을 용도대로 사용했다면 임료 상당의 사용이익을 얻은 것이다. 전체 영업이 적자였다는 이유로 그 이익을 부정할 수 없다.", "pages": [33], "sourceHash": "d45375170d69fc8cbb032428dbabb8c77c0dc764a332310947f5cfef655e5875"}], "민법4_강의자료(사무관리, 부당이득)-65": [{"key": "29", "start": 0, "end": 2, "citation": "대법원 1975. 4. 22. 선고, 74다1184 전원합의체 판결", "summary": "토지의 불법점유자가 지급의무를 부인하는 등 미리 청구할 필요가 있다면, 앞으로 발생할 임료 상당의 부당이득도 청구할 수 있다.", "pages": [33], "sourceHash": "158f7628defe4bacd40a7bfce5bd48dbdf51e560c8dcd57a7f91dd1b8a325fbd"}], "민법4_강의자료(사무관리, 부당이득)-66": [{"key": "30", "start": 0, "end": 2, "citation": "대법원 1998. 4. 24. 선고 97다28568 판결", "summary": "손해의 현실적 발생은 사회통념에 따라 객관적·합리적으로 판단한다. 매도인의 초과대출 때문에 매수인이 소유권이전청구권을 지키려 추가 변제를 해야 하는 상황도 현실적 손해가 될 수 있다.", "pages": [34], "sourceHash": "6f27ac25d76bc33747e50c7f08811e1dffff633bc797c10af4807d094d449e90"}], "민법4_강의자료(사무관리, 부당이득)-67": [{"key": "31", "start": 0, "end": 2, "citation": "대법원 1981. 1. 13. 선고 80다380 판결", "summary": "부당이득에서 말하는 ‘타인의 재산’에는 이미 귀속된 재산뿐 아니라 당연히 그 사람에게 귀속돼야 할 재산도 포함된다.", "pages": [34], "sourceHash": "655c83f09a295ed45b9960bb35315508681de31179885967f8d749957e6b3b8e"}], "민법4_강의자료(사무관리, 부당이득)-68": [{"key": "32", "start": 0, "end": 1, "citation": "대법원 1989. 1. 24. 선고 88다카6006 판결", "summary": "지방자치단체가 권원이나 적법한 보상 없이 타인의 토지를 도로로 점유하면 사용이익의 반환을 청구할 수 있다. 도로라는 이유만으로 부당이득청구가 배제되지 않는다.", "pages": [34], "sourceHash": "d86a210331168f57470bdc165b2fdd4afc25fc85dfe736dc10b67e19cd2dc523"}], "민법4_강의자료(사무관리, 부당이득)-69": [{"key": "33", "start": 0, "end": 2, "citation": "대법원 1982. 5. 25. 선고 81다카1061 판결", "summary": "임야 개량으로 소유자가 얻은 이익을 반환하게 하려면, 먼저 비용·노무 제공자의 손실을 확정하고 이득액과 비교해야 한다. 반환은 그 손실의 범위로 제한된다.", "pages": [34, 35], "sourceHash": "23d38b3c3c49ccd00650586594e666f19db55ba8829925efb67c513f0bdcc556"}], "민법4_강의자료(사무관리, 부당이득)-71": [{"key": "34", "start": 0, "end": 2, "citation": "대법원 2010. 8. 19. 선고 2010다31860,31877 판결", "summary": "제3자를 위한 계약의 기본관계가 무효·해제되면 원칙적으로 낙약자와 요약자 사이에서 청산해야 한다. 낙약자가 수익자인 제3자에게 직접 부당이득반환을 청구할 수는 없다.", "pages": [36], "sourceHash": "29c92f2fdf59521775529c4989f45f0a6ebaf237d533d03d3e602034cd6e08d1"}], "민법4_강의자료(사무관리, 부당이득)-73": [{"key": "35", "start": 0, "end": 5, "citation": "대법원 2021. 7. 22. 선고 2019다277812 전원합의체 판결", "summary": "보험금을 부정 취득할 목적으로 체결해 무효인 보험계약의 보험금 반환청구에는 상법을 유추해 5년의 상사소멸시효를 적용한다.", "pages": [37], "sourceHash": "67771f7ddd13c2f1ac38a2827fcd67fac43d119c5cf21b8da76356f742693d0d"}], "민법4_강의자료(사무관리, 부당이득)-75": [{"key": "36", "start": 0, "end": 1, "citation": "대판 2002. 12. 26, 2000다21123", "summary": "부동산실명법 시행 전 계약명의신탁에서 유예기간이 지나 수탁자가 완전한 소유권을 취득한 경우, 부당이득의 반환 대상은 매수자금이 아니라 부동산 자체다.", "pages": [38], "sourceHash": "688a7a4fb3e9022d628301b2292d6d40c8b1b8844a6a1c83fc9fcddf734832aa"}], "민법4_강의자료(사무관리, 부당이득)-76": [{"key": "37", "start": 0, "end": 1, "citation": "대판 2005. 1. 28, 2002다66922", "summary": "부동산실명법 시행 후 계약명의신탁에서 선의의 매도인으로부터 소유권을 취득한 수탁자는, 신탁자에게 부동산 자체가 아니라 제공받은 매수자금을 반환한다.", "pages": [38], "sourceHash": "55b9c339ae4975c8519a6f4237f0e785c485d37b70ee09c09aed5fce70b676e5"}], "민법4_강의자료(사무관리, 부당이득)-77": [{"key": "38", "start": 0, "end": 2, "citation": "대법원 2001. 3. 13. 선고 99다26948 판결(공 2001, 863)", "summary": "법률상 원인 없이 채권을 얻었으나 아직 추심하지 않았다면 그 채권 자체를 반환해야 한다. 이미 변제받았다면 그 금액을 반환한다.", "pages": [38, 39], "sourceHash": "1c0a22f272a5abb0c823bb245dbe44529ec50d5f6d08f2b64b4812f7b30f1adb"}], "민법4_강의자료(사무관리, 부당이득)-78": [{"key": "39", "start": 0, "end": 2, "citation": "대법원 1970. 10. 30. 선고 70다1390․1391(집 18, 246)", "summary": "무효인 농지임대차의 임료 지급이 당연히 불법원인급여가 되는 것은 아니다. 수령자는 특별한 사정이 없으면 악의로 반환할 의무를 지며, 받은 벼가 남아 있지 않다는 점은 수령자가 증명해야 한다.", "pages": [39], "sourceHash": "2ce4ca1742e10c84e1a344e09a660e7ab991a3d8bd4029183fd693a245002f79"}], "민법4_강의자료(사무관리, 부당이득)-79": [{"key": "40", "start": 0, "end": 1, "citation": "대판 1996. 12. 10,96다32881", "summary": "금전으로 얻은 부당이득은 소비 여부와 관계없이 현존하는 것으로 추정된다.", "pages": [39], "sourceHash": "b6afcc79bb67ac2354d24101b15a70e7c028aae7b7261d08a4b102b646f7cbcf"}], "민법4_강의자료(사무관리, 부당이득)-80": [{"key": "41", "start": 0, "end": 3, "citation": "대판 2008. 1. 18, 2005다34711", "summary": "부당이득 반환은 손실자가 통상 얻었을 이익의 범위에 한정된다. 거액의 매매대금에서 발생한 정기예금 이자는 통상 취득할 이익으로서 반환 범위에 포함될 수 있다.", "pages": [39], "sourceHash": "0a64eb821c6aee76ead4aaedda4dbf86ebd38f7c9139af42f8644fa1acb77f76"}], "민법4_강의자료(사무관리, 부당이득)-81": [{"key": "42", "start": 0, "end": 1, "citation": "대법원 2011. 6. 10. 선고 2010다40239 판결", "summary": "타인의 부동산을 무단 처분한 수익자는 그 매각으로 발생한 양도소득세 등 비용을 반환할 이득에서 공제할 수 없다.", "pages": [40], "sourceHash": "066817b578aee7024d0d77efb36b7cc44ccc0291592c0363f4fb0e8bf52b31a7"}], "민법4_강의자료(사무관리, 부당이득)-82": [{"key": "43", "start": 0, "end": 1, "citation": "대판 1974. 7. 26, 73다1637", "summary": "토지의 이용가치를 높이는 성토·매립·석축공사의 결과가 남아 있다면 그 공사비 상당의 현존이익을 인정할 수 있다. 다만 반환액은 공사 당시 지출한 손실액을 넘을 수 없다.", "pages": [40], "sourceHash": "518c060fa56725090a9a3ba4adde20c7467408590ac0ffca5aca297443dc508c"}], "민법4_강의자료(사무관리, 부당이득)-83": [{"key": "44", "start": 0, "end": 1, "citation": "대판 1981. 8. 11, 80다2885", "summary": "권원 없이 타인의 토지에서 얻은 농작물을 소비해 원물반환이 불가능하면 가액을 반환한다. 특별한 사정이 없으면 처분 당시의 대가를 기준으로 한다.", "pages": [40], "sourceHash": "4444cfb3ac0b83e490d4c7eb6fba0d520520626d7d986c0e48bea2aebaac8827"}], "민법4_강의자료(사무관리, 부당이득)-84": [{"key": "45", "start": 0, "end": 2, "citation": "대판 1995. 5. 12, 94다25551", "summary": "무단 굴취한 토석의 반환가액에서는 토석 취득·이용에 든 비용과 수익자 자신의 노력으로 얻은 이윤을 제외한다. 토석 자체에서 당연히 생길 이익까지 제외되는 것은 아니다.", "pages": [40], "sourceHash": "7ee5a6831244006a8c94bb0ac8b78701a293302c20cadb49c456f2866c535130"}], "민법4_강의자료(사무관리, 부당이득)-85": [{"key": "46", "start": 0, "end": 1, "citation": "대법원 1974. 7. 26. 선고 73다1637 판결", "summary": "공사 결과가 남아 있다면 그 공사비가 현존이익이 될 수 있지만, 선의 수익자는 손실자의 손실액을 한도로 반환하면 된다.", "pages": [41], "sourceHash": "7b8a2c6685032e380743642a08013df06eb5e9901097d565c8ffc40a47092151"}], "민법4_강의자료(사무관리, 부당이득)-88": [{"key": "47", "start": 0, "end": 1, "citation": "대법원 2018. 4. 12. 선고 2017다229536 판결", "summary": "악의의 수익자란 이익을 보유할 법률상 원인이 없음을 아는 사람이다. 반환의무를 발생시키는 사실만 알았다는 것으로는 부족하며 악의는 이를 주장하는 쪽이 증명한다.", "pages": [41, 42], "sourceHash": "7d6af9d9761e1f12280bd13bb7ddfd845b74a10ed8981f7d7671a08f8456afe2"}], "민법4_강의자료(사무관리, 부당이득)-89": [{"key": "48", "start": 0, "end": 1, "citation": "대판 1993. 2. 26, 92다48635,48642", "summary": "사기를 이유로 매매를 취소한 매수인도 취소 후에는 법률상 원인 없음을 아는 수익자가 될 수 있다. 매도인의 대금반환의무와 동시이행관계라는 사정은 이를 바꾸지 않는다.", "pages": [42], "sourceHash": "3ca2e0de522a2e8a252eda214ea8b9e85e2772f3525b5be3cd5b8d1d417f4848"}], "민법4_강의자료(사무관리, 부당이득)-90": [{"key": "49", "start": 0, "end": 3, "citation": "대판 1995. 11. 21, 94다45753", "summary": "퇴직처분의 무효를 다투며 퇴직금을 받은 근로자를 곧바로 악의의 수익자라고 할 수 없다. 부당이득 반환채무의 지체책임은 이행청구를 받은 때부터 생긴다.", "pages": [42], "sourceHash": "ec4de5089114f204fe7a820fc088c4242a61644cd7a92693818cdd84b13f008e"}], "민법4_강의자료(사무관리, 부당이득)-91": [{"key": "50", "start": 0, "end": 1, "citation": "대법원 2014. 1. 23. 선고 2012다95325 판결", "summary": "선의의 수익자가 패소해 악의로 간주되는 ‘소를 제기한 때’는 소장 부본이 피고에게 송달된 때를 뜻한다. 그 밖의 악의는 주장하는 사람이 증명해야 한다.", "pages": [42], "sourceHash": "4f8ce6529c50917d7637d29f1b5c1eadfdc57ddb056ad9e39cdce4887ca4b70d"}], "민법4_강의자료(사무관리, 부당이득)-92": [{"key": "51", "start": 0, "end": 1, "citation": "대판 2002. 2. 5, 2001다66369", "summary": "무효인 차입으로 받은 돈을 임원이 임의로 소비했더라도 새마을금고의 부당이득반환의무는 남는다. 대표 임원들이 차입의 무효를 알았다면 금고도 악의의 수익자가 된다.", "pages": [42], "sourceHash": "c482520b8ccaeaada7437fc9a24176c6a0d8fd6d5b04ee3a1efcaed09d9a62bb"}], "민법4_강의자료(사무관리, 부당이득)-97": [{"key": "52", "start": 0, "end": 2, "citation": "대법원 1981. 9. 22. 선고 81다233 판결", "summary": "선의의 토지 점유자는 과실을 취득하므로, 점유·경작으로 얻은 이득을 소유자에게 반환할 의무가 없다.", "pages": [43], "sourceHash": "c9d58403e706e67489ca81981132a1b8108d9810114570b9baf7429f12f2b576"}], "민법4_강의자료(사무관리, 부당이득)-98": [{"key": "53", "start": 0, "end": 2, "citation": "대법원 1996. 1. 26. 선고 95다44290 판결", "summary": "건물의 사용이익도 과실에 준한다. 선의의 점유자는 권원 없이 타인의 건물을 사용했더라도 그 사용이익을 반환할 의무가 없다.", "pages": [43, 44], "sourceHash": "dcb85a931aa7fbcf3236acbdf51d899ad43f5c19de3f4c8843a5954e1cb8a144"}], "민법4_강의자료(사무관리, 부당이득)-99": [{"key": "54", "start": 0, "end": 1, "citation": "대법원 1996. 12. 10. 선고 96다32881 판결", "summary": "금전으로 취득한 부당이득은 소비 여부와 관계없이 현존하는 것으로 추정된다.", "pages": [44], "sourceHash": "30f2d4f57f21196f6b64cfaa21b937774d68fedf4f87214cbd6c3a344e0a1ee8"}], "민법4_강의자료(사무관리, 부당이득)-100": [{"key": "55", "start": 0, "end": 1, "citation": "대법원 1970. 10. 30. 선고 70다1390,1391 판결", "summary": "임료로 받은 벼는 특별한 사정이 없으면 남아 있는 것으로 본다. 현재 존재하지 않는다는 점은 받은 사람이 증명해야 한다.", "pages": [44], "sourceHash": "799e5c45524cc729ed13637b66bd3fcafd518d8045b760b7802b7cad7cd16171"}], "민법4_강의자료(사무관리, 부당이득)-101": [{"key": "56", "start": 0, "end": 1, "citation": "대법원 1970. 2. 10. 선고 69다2171 판결", "summary": "선의 수익자에게 부당이득반환을 청구할 때에는 반환청구자가 이익의 현존을 증명할 책임을 진다.", "pages": [44], "sourceHash": "c625f6d0d95e346942714eea838867e6b559a979275c76e1162ca13d48a73091"}], "민법4_강의자료(사무관리, 부당이득)-102": [{"key": "57", "start": 0, "end": 2, "citation": "대법원 2003. 12. 12. 선고 2001다37002 판결(미간행)", "summary": "금전을 받자마자 당사자들의 사전 합의에 따라 제3자에게 넘겼다면 금전의 현존 추정이 깨질 수 있다. 이때 제3자에 대한 반환채권 자체나 그 평가액이 현존이익이 된다.", "pages": [44], "sourceHash": "154c0e82418a5449d0ca621703d85f1793589a568451931226ab6b19b3291fe9"}], "민법4_강의자료(사무관리, 부당이득)-103": [{"key": "58", "start": 0, "end": 2, "citation": "대법원 2022. 10. 14. 선고 2018다244488 판결", "summary": "급부자의 지시·합의에 따라 돈을 사용했다면 금전의 현존 추정이 번복될 수 있다. 투자중개업자가 위탁대로 거래하고 정산잔액도 돌려줬다면 현존이익이 없을 수 있다.", "pages": [44, 45], "sourceHash": "3a83814d57654eee9a735d4a37fd38d150d54a1d6da3b3da9714c386e1a659eb"}], "민법4_강의자료(사무관리, 부당이득)-105": [{"key": "59", "start": 0, "end": 3, "citation": "대판 2000. 4. 11, 99다4238", "summary": "위법한 청산금 부과를 감액·취소하면 차액은 부당이득이 된다. 행정주체는 특별한 사정이 없으면 적어도 그 취소 때부터 법률상 원인 없음을 아는 것으로 본다.", "pages": [45, 46], "sourceHash": "879550baf481d854ac89a459fa2d7ac08b48c7869bc2dffe1ba4edd3db7ef112"}], "민법4_강의자료(사무관리, 부당이득)-106": [{"key": "60", "start": 0, "end": 2, "citation": "대판 2003. 11. 14, 2001다61869", "summary": "악의의 점유자는 사용이익에 이자를 붙여 반환해야 한다. 그 이자의 지급도 지체하면 지연손해금을 부담한다.", "pages": [46], "sourceHash": "b1e80de0f11d4694afc46e4d3252dc76e17cc1f3b2ea03066e449e3efa0d42b8"}], "민법4_강의자료(사무관리, 부당이득)-107": [{"key": "61", "start": 0, "end": 2, "citation": "대법원 1987. 1. 20. 선고 86다카1372 판결", "summary": "본권에 관한 소송에서 패소한 선의 점유자는 그 소가 제기된 때부터 악의 점유자로 간주된다. 소유권이전등기 말소소송도 이에 해당한다.", "pages": [46], "sourceHash": "9a83bede2f607f54271d328814b7b587adf6e9f433e29b1dd8e81fa7aa2a87f5"}, {"key": "61.2", "start": 2, "end": 3, "citation": "2017. 3. 9. 선고 2016다47478 판결", "summary": "무효인 매매의 대금을 반환하는 악의 수익자는 법정이자를 붙여야 한다. 이 이자는 지체에 따른 배상이 아니라 부당이득반환이므로 동시이행관계와 관계없이 발생한다.", "pages": [46], "sourceHash": "09f9be13a0c2ef0d0782af80f5e8d816465dc2b2e034bbb65ccf2fab3369c9cc"}], "민법4_강의자료(사무관리, 부당이득)-108": [{"key": "62", "start": 0, "end": 3, "citation": "대법원 2009. 1. 15. 선고 2008다58367 판결", "summary": "의사무능력자의 대출금이 제3자에 대한 채권으로 남아 있다면 그 채권이 현존이익이 된다. 그 채권양도의무와 근저당권 말소의무는 동시이행관계다.", "pages": [46], "sourceHash": "3e112afe95cb724371392c6a76afc9e9442a7fc9e409d8bd5f22784088409ef4"}], "민법4_강의자료(사무관리, 부당이득)-110": [{"key": "63", "start": 0, "end": 1, "citation": "대법원 2003. 12. 26. 선고 2001다46730 판결", "summary": "계약상대방의 지시로 제3자에게 직접 지급한 단축급부에서는, 원칙적으로 지급자가 제3자에게 직접 부당이득반환을 청구할 수 없다.", "pages": [47], "sourceHash": "b45f745c4afab8651bb12bafc37b9f956d74942796184b5e436f550234112291"}], "민법4_강의자료(사무관리, 부당이득)-111": [{"key": "64", "start": 0, "end": 1, "citation": "대법원 2008. 9. 11. 선고 2006다46278 판결", "summary": "단축급부를 받은 제3자가 지급자와 계약상대방 사이의 계약상 하자를 알았더라도, 지급자가 그 제3자에게 직접 부당이득반환을 청구할 수는 없다.", "pages": [47, 48], "sourceHash": "4d23b82018d8d25576bdc7d5841ed0397f63d7f20a39bf4f6543418347cc5bb5"}], "민법4_강의자료(사무관리, 부당이득)-112": [{"key": "65", "start": 0, "end": 1, "citation": "대법원 2015. 5. 29. 선고 2012다92258 판결", "summary": "제3채무자가 질권자에게 지급한 뒤 입질채권의 원인계약이 무효로 밝혀져도, 원칙적으로 질권설정자에게 반환을 구해야 한다. 질권자에게 직접 청구할 수는 없다.", "pages": [48], "sourceHash": "f9ffe202013426d124a2b252181ea220ac461ac85d95319f59de15630d440282"}], "민법4_강의자료(사무관리, 부당이득)-113": [{"key": "66", "start": 0, "end": 1, "citation": "대법원 2017. 7. 11. 선고 2013다55447 판결", "summary": "계약의 무효나 해제를 이유로 단축급부의 수령자인 제3자에게 직접 반환을 청구할 수 없다. 이는 계약상 위험을 제3자에게 떠넘기고 그 항변권을 해치기 때문이다.", "pages": [48], "sourceHash": "326863f69da17265d2f17cf4cab626963d7ec438c431c106eae0759fad18a63a"}], "민법4_강의자료(사무관리, 부당이득)-114": [{"key": "67", "start": 0, "end": 2, "citation": "대법원 2018. 7. 12. 선고 2018다204992 판결", "summary": "단축급부에서는 원칙적으로 제3자에 대한 직접 반환청구가 허용되지 않는다. 제3자를 위한 계약인지 여부는 제3자에게 직접 권리를 주려는 당사자의 의사를 종합적으로 해석해 판단한다.", "pages": [48], "sourceHash": "a991627e16001366ebffe1428d9d736b1f6513378ba878ac7ce85b6d803dec5f"}], "민법4_강의자료(사무관리, 부당이득)-115": [{"key": "68", "start": 0, "end": 1, "citation": "대법원 2002. 8. 23 선고 99다66564, 66571 판결", "summary": "계약상 급부로 제3자도 이익을 얻었다는 이유만으로 그 제3자에게 직접 부당이득반환을 청구할 수 없다. 계약상 위험배분과 다른 채권자의 이익, 제3자의 항변권을 보호해야 한다.", "pages": [49], "sourceHash": "40607b36c367f7d95dc9946fe870f0336834eea833326cd06c06512aa4af746a"}], "민법4_강의자료(사무관리, 부당이득)-116": [{"key": "69", "start": 0, "end": 1, "citation": "대법원 2013. 6. 27. 선고 2011다17106 판결", "summary": "사무관리로 결과적인 이익을 얻은 제3자에게도 직접 부당이득반환을 청구할 수 없다. 관리자는 사무관리의 본인에게 비용상환 등을 구해야 한다.", "pages": [49], "sourceHash": "f3625bdad8fdec6e3c7e2c6ef96ba14bd8bd32d8cb32de59b1199748ec9313b1"}], "민법4_강의자료(사무관리, 부당이득)-118": [{"key": "70", "start": 0, "end": 1, "citation": "대법원 2003. 6. 13. 선고 2003다8862 판결", "summary": "횡령금으로 변제받은 채권자는 그 출처에 관해 악의 또는 중과실이 있으면 피해자에게 반환해야 한다. 단순한 과실만 있다면 법률상 원인 없는 취득으로 보지 않는다.", "pages": [50], "sourceHash": "b203137969396e4b3f436df782150636c78e738e5b2930292412ff4bdeb6df43"}], "민법4_강의자료(사무관리, 부당이득)-119": [{"key": "71", "start": 0, "end": 1, "citation": "대법원 2012. 1. 12. 선고 2011다74246 판결", "summary": "횡령금을 변제나 증여로 받은 사람은 그 출처에 관해 악의·중과실이 없는 한 피해자에 대한 관계에서도 법률상 원인 있는 취득을 한다.", "pages": [50], "sourceHash": "bbb88404ee65ddad85a35bd7e0daeb26fe5531a448f003e116e45cd0b3d4fca9"}], "민법4_강의자료(사무관리, 부당이득)-120": [{"key": "72", "start": 0, "end": 2, "citation": "대법원 2003. 7. 25. 선고 2001다64752 판결", "summary": "임대차 등 적법한 권원으로 점유하며 쓴 유익비는 그 계약관계에 따라 상대방에게 청구해야 한다. 새 소유자에게 별도로 민법 제203조의 비용상환을 청구할 수는 없다.", "pages": [51], "sourceHash": "20e7b0c1045d53fb75bed295c6e32cfa615e8d6794b1083615dee426fb2c3e41"}], "민법4_강의자료(사무관리, 부당이득)_보완자료-3": [{"key": "73", "start": 0, "end": 2, "citation": "대법원 2009. 9. 24. 선고 2009다15602 판결", "summary": "소유권유보 자재가 건물에 부합해도 보상청구에는 부당이득의 요건이 필요하다. 건축주가 소유권유보 사실을 과실 없이 몰랐다면 자재의 이익을 보유할 법률상 원인이 인정된다.", "pages": [53], "sourceHash": "9f8ee4bb5686b5b4cbcdf79a60daf335ca553d0909baf378f5732b226b0e842f"}], "민법4_강의자료(사무관리, 부당이득)_보완자료-4": [{"key": "74", "start": 0, "end": 3, "citation": "대법원 2018. 3. 15. 선고 2017다282391 판결", "summary": "첨부에 따른 보상청구도 부당이득의 요건을 모두 갖춰야 한다. 자재의 소유권유보를 과실 없이 몰랐던 건축주가 보호되는 법리는 무권대리인을 거친 자재 공급에도 적용된다.", "pages": [53], "sourceHash": "e173dc294d505cdd995f11439fde53e5626753a74c2854e751342fe6127b172c"}], "민법4_강의자료(사무관리, 부당이득)-129": [{"key": "75", "start": 0, "end": 2, "citation": "대법원 1992. 9. 8. 선고, 92다15550 판결", "summary": "무권리자의 처분을 원권리자가 추인하면 특별한 사정이 없는 한 그 효력이 원권리자에게 미친다. 공유지분을 무단 매도한 경우에도 추인을 전제로 매매대금의 반환을 청구할 수 있다.", "pages": [54, 55], "sourceHash": "48c7cff99a535f1dcc8a295d93c0ed6bf93c4edca9e629289a16fd98a0fea330"}], "민법4_강의자료(사무관리, 부당이득)-139": [{"key": "76", "start": 0, "end": 1, "citation": "대법원 1998. 11. 13. 선고 97다58453 판결", "summary": "보상의무가 있다고 잘못 알고 보상금을 지급했다면 반환을 청구할 수 있다. 의무가 없음을 몰랐던 데 과실이 있어도 마찬가지다.", "pages": [59], "sourceHash": "f827c632b2ca8ba67f8d0811797a4951834e8ac62363e701cf865fbc6ac895ab"}], "민법4_강의자료(사무관리, 부당이득)-140": [{"key": "77", "start": 0, "end": 1, "citation": "대법원 2010. 07. 15. 선고 2008다39786 판결", "summary": "채무가 없다고 생각하면서 지급했더라도 강제집행으로 인한 중대한 손해를 피하려 부득이하게 변제한 경우에는 반환청구권을 잃지 않는다.", "pages": [59], "sourceHash": "731143d26637fda9d54292b2ee83f0277e4759f65088ceffc141ca9c096e229c"}], "민법4_강의자료(사무관리, 부당이득)-142": [{"key": "78", "start": 0, "end": 1, "citation": "대법원 1991. 8. 13. 선고 91다6856 판결", "summary": "기한 전 변제에서 말하는 착오는 변제기가 아직 오지 않았음을 모른 경우다. 기한 전임을 알면서 변제했다면 기한의 이익을 포기한 것으로 본다.", "pages": [60], "sourceHash": "3c5b8fa1eb307208c714c5218708321fb423159cf70531fc2c7c98dfbe01eee4"}], "민법4_강의자료(사무관리, 부당이득)-145": [{"key": "79", "start": 0, "end": 2, "citation": "대법원 2007. 12. 27. 선고 2007다54450 판결", "summary": "보장사업자가 착오로 보험회사의 채무를 대신 변제한 뒤 피해자의 채권이 선의로 시효 소멸했다면, 민법 제745조에 따라 보험회사 등에 구상할 수 있다.", "pages": [61], "sourceHash": "3ce0f608117849365c296c644770c3cf48157374e485b6925c34e6f3bdf1da20"}], "민법4_강의자료(사무관리, 부당이득)-149": [{"key": "80", "start": 0, "end": 1, "citation": "대법원 1995. 8. 11. 선고 94다54108 판결", "summary": "도박채무를 담보하는 근저당권만 설정했다면 이익이 종국적으로 귀속된 것은 아니다. 부동산 소유자는 불법원인급여 규정에 막히지 않고 등기말소를 구할 수 있다.", "pages": [62], "sourceHash": "50aa6a7082f263e2cf84c3207a8e8e73866a0ea676376fc2bdda0e44c6bc6fb2"}], "민법4_강의자료(사무관리, 부당이득)-150": [{"key": "81", "start": 0, "end": 2, "citation": "대법원 1994. 12. 22. 선고 93다55234 판결", "summary": "불법원인급여의 반환 제한은 종국적으로 귀속된 이익에 적용된다. 별도의 경매 실행이 필요한 근저당권 설정은 이에 해당하지 않아 말소를 청구할 수 있다.", "pages": [63], "sourceHash": "5180fc07809be71975df916cf7b7726082925106a7aba16d57745b4c66209b62"}], "민법4_강의자료(사무관리, 부당이득)-151": [{"key": "82", "start": 0, "end": 3, "citation": "대법원 1989. 9. 29. 선고 89다카5994 판결", "summary": "도박채무의 양도담보로 소유권이전등기까지 마친 경우에는 불법원인급여를 이유로 그 말소를 청구할 수 없다. 소유권에 기한 반환청구도 제한된다.", "pages": [63], "sourceHash": "33c608c6e6732366de24aec38b1e2f4a8a8d187582ec55026f8825b5b093ea58"}], "민법4_강의자료(사무관리, 부당이득)-152": [{"key": "83", "start": 0, "end": 3, "citation": "대법원 1991. 3. 22. 선고 91다520 판결", "summary": "면허 취득을 위한 불법 청탁금은 단순 보관금이라는 이유로 돌려받을 수 없다. 청탁 실패 시 돌려주기로 한 약정도 이 사건에서는 사회질서에 반해 무효라고 보았다.", "pages": [63], "sourceHash": "931d793db6b7ed894405a80578a894360fd1b591f6a56e78feb34148967e4e69"}], "민법4_강의자료(사무관리, 부당이득)-153": [{"key": "84", "start": 0, "end": 1, "citation": "대법원 1983. 11. 22. 선고 83다430 판결", "summary": "불법원인급여의 ‘불법’은 선량한 풍속이나 사회질서 위반을 뜻한다. 단순히 법률의 금지규정을 위반했다는 사정만으로는 부족하다.", "pages": [64], "sourceHash": "eb2da349c486f240010505bebac5a4e5db34d17d1f2cf11b11d825818fa4d62b"}], "민법4_강의자료(사무관리, 부당이득)-154": [{"key": "85", "start": 0, "end": 2, "citation": "대법원 2001. 5. 29. 선고 2001다1782 판결", "summary": "담배 판매 제한이나 사재기 금지를 위반한 거래라도 그 자체로 반윤리적이지 않다면 불법원인급여가 아니다. 이 사건 담배구입대금의 반환청구는 허용된다.", "pages": [64], "sourceHash": "b0af6e1087ca28a7a03211984828c81c3a0846ddcd90a9321fa90373c34c684b"}], "민법4_강의자료(사무관리, 부당이득)-155": [{"key": "86", "start": 0, "end": 3, "citation": "대법원 2017. 3. 15. 선고 2013다79887, 79894 판결", "summary": "농지임대차가 법률에 위반돼 무효여도 곧바로 불법원인급여가 되지는 않는다. 현저한 반사회성 등 특별한 사정이 없다면 임차인은 그 법리로 사용이익 상당의 배상을 거절할 수 없다.", "pages": [64, 65], "sourceHash": "a483ef656e861741a86d51a7e67c188ca637f9013d028d6dd4bc864e565f5337"}], "민법4_강의자료(사무관리, 부당이득)-156": [{"key": "87", "start": 0, "end": 1, "citation": "대법원 2017. 4. 26. 선고 2016도18035 판결", "summary": "범죄수익 은닉을 위해 건넨 수표는 불법원인급여로 수령자에게 소유권이 귀속된다. 이 사건에서는 수령자가 이를 임의로 소비해도 횡령죄가 성립하지 않는다고 보았다.", "pages": [65], "sourceHash": "fcb8959c9e13c17e305efe64a508aea6110a331c94af0098e11a295fff982254"}], "민법4_강의자료(사무관리, 부당이득)-159": [{"key": "88", "start": 0, "end": 2, "citation": "대판 1997. 10. 24, 95다49530", "summary": "수익자의 불법성이 급여자보다 현저히 크고 급여자의 불법성이 미약하다면 예외적으로 반환을 청구할 수 있다. 사기적 내기바둑과 폭리로 받은 주택의 반환을 인정한 사례다.", "pages": [66], "sourceHash": "adb511be0dc1393c94447d95bb0a932341e8c64f8fd877d87f75167aa64db618"}], "민법4_강의자료(사무관리, 부당이득)-160": [{"key": "89", "start": 0, "end": 1, "citation": "대판 1999. 9. 17, 98도2036", "summary": "성매매 수익 분배약정이 무효여도 업주의 불법성이 현저히 크다면 맡긴 돈의 반환을 청구할 수 있다. 이를 임의로 소비한 업주에게는 횡령죄가 성립한다.", "pages": [66], "sourceHash": "878d499562742e2652d255161c01a94fe6012a2d5e068ea97701b673a246a541"}], "민법4_강의자료(사무관리, 부당이득)-161": [{"key": "90", "start": 0, "end": 3, "citation": "대법원 2007. 2. 15. 선고 2004다50426 전원합의체 판결", "summary": "다수의견은 사회통념상 허용 한도를 현저히 넘는 고리 약정을 무효로 보고 초과이자의 반환을 인정했다. 수록된 반대의견은 불법원인급여의 반환 제한을 이유로 반대했다.", "pages": [66, 67], "sourceHash": "b4e9d60e9bfddeb76ee84ae1a1929d9a7ffd10c59ece0e8d60d51e056fe1e214"}], "민법4_강의자료(사무관리, 부당이득)-162": [{"key": "91", "start": 0, "end": 1, "citation": "대법원 1979. 11. 13. 선고 79다483 전원합의체 판결", "summary": "불법원인급여자는 부당이득뿐 아니라 소유권을 근거로도 급여물의 반환을 청구할 수 없다. 그 결과 급여물의 소유권은 수령자에게 귀속된다.", "pages": [67], "sourceHash": "c34d16e6dd69844ad49580d773952d374eab063f79658bf6257302e04a495da8"}], "민법4_강의자료(사무관리, 부당이득)-163": [{"key": "92", "start": 0, "end": 1, "citation": "대법원 2013. 8. 22. 선고 2013다35412 판결", "summary": "불법원인급여로 준 재산을 손해배상 형식으로 되찾는 것도 원칙적으로 허용되지 않는다. 수령자에게만 불법성이 있거나 그 불법성이 현저히 큰 경우 등은 예외다.", "pages": [67, 68], "sourceHash": "20ad0941e49352c6e69d3cb7ce3d252c08c7fabd4ec6a6cc70761f9ea411d9bd"}], "민법4_강의자료(사무관리, 부당이득)-164": [{"key": "93", "start": 0, "end": 1, "citation": "대법원 1983. 4. 26. 선고 83다카57 판결", "summary": "반사회적 이중양도로 등기청구권을 침해받은 제1매수인은 매도인을 대위해 제2취득자의 등기말소를 구할 수 있다. 직접 말소청구인지 대위청구인지 불명확하다면 법원이 석명해야 한다.", "pages": [68], "sourceHash": "4ef83d4bb9d52ad73257b63c31b0abbe25caca9e85a7f5a404c54c32e0bd6556"}], "민법4_강의자료(사무관리, 부당이득)-165": [{"key": "94", "start": 0, "end": 2, "citation": "대법원 2010. 5. 27. 선고 2009다12580 판결", "summary": "불법원인급여 후 별도로 체결한 반환약정은 그 약정 자체가 사회질서에 반하지 않는 한 유효하다. 원래 급여가 불법이었다는 이유만으로 반환약정까지 무효가 되지는 않는다.", "pages": [68], "sourceHash": "c75cc45d0b52610491ef8fffc4ac67d08792a0c9f8ca29ddeaa52123e5363fe7"}], "민법4_강의자료(불법행위)-7": [{"key": "95", "start": 0, "end": 3, "citation": "대법원 2008. 2. 1. 선고 2006다6713 판결", "summary": "경찰의 총기사용에 형사상 무죄가 확정됐더라도 민사상 과실책임은 별도로 판단한다. 필요한 한도를 넘는 총기사용에는 손해배상책임이 인정될 수 있다.", "pages": [72], "sourceHash": "760adb18d6ccad30539813891d14107bbcccd2ea19cdec88774f09dcd4921ddb"}], "민법4_강의자료(불법행위)-18": [{"key": "96", "start": 0, "end": 2, "citation": "대법원 2017. 7. 18. 선고 2016다216953 판결", "summary": "자기신체사고보험의 고의 면책은 보험사고 전체를 보아 판단한다. 자배법상 승객의 고의·자살에 따른 면책도 자유로운 의사결정에 기초한 의식적 행위에 한정된다.", "pages": [75, 76], "sourceHash": "b751300e05029903deddbc0b63be5e32e22c62cbb21b1587c47f601bb02cddc2"}], "민법4_강의자료(불법행위)-19": [{"key": "97", "start": 0, "end": 1, "citation": "헌법재판소 1998. 5. 28. 96헌가4 전원재판부", "summary": "운행자에게 무상·호의동승자를 포함한 승객의 손해를 과실 여부와 관계없이 배상하게 하는 규정은 합리적 재산권 제한으로서 헌법에 위반되지 않는다.", "pages": [76], "sourceHash": "ff19a7e7138a38f8b4e06a6d7cacca58c8109d04b5b60576643d96d3333dd34e"}], "민법4_강의자료(불법행위)-23": [{"key": "98", "start": 0, "end": 1, "citation": "대법원 2010. 3. 11. 선고 2009다5643 판결", "summary": "포털이 저작권 침해를 구체적으로 알았거나 알 수 있음이 명백하고 관리·통제도 가능했다면 삭제·차단 의무를 진다. 이를 위반하면 부작위 방조에 따른 공동불법행위가 성립할 수 있다.", "pages": [78], "sourceHash": "1d307d5e22f0da27f9885384706223b7ff351bf3f4291c2b652d6103e4070d0c"}], "민법4_강의자료(불법행위)-24": [{"key": "99", "start": 0, "end": 1, "citation": "대법원 1999. 6. 11. 선고 98다22963 판결", "summary": "소유권이전등기청구권을 가압류당한 제3채무자는 등기청구소송에서 그 사실을 주장·증명해야 한다. 이를 게을리해 등기·전매로 채권자에게 손해가 생기면 불법행위책임을 질 수 있다.", "pages": [78], "sourceHash": "7629152b44c212fb6f255415c28eaff60e9abb8ae32e8dd921f261685d0e1dc4"}], "민법4_강의자료(불법행위)-26": [{"key": "100", "start": 0, "end": 1, "citation": "대법원 1994. 12. 2. 선고 93다111 판결", "summary": "조합장이 어음 남발·횡령 위험과 부정대출을 알고도 필요한 방지조치를 하지 않았다면, 조합에 대한 불법행위로 손해배상책임을 진다.", "pages": [79], "sourceHash": "fb9005252f9da345394a57f3872f349c4f1068c953925e2e55338fbd7249a2b8"}], "민법4_강의자료(불법행위)-28": [{"key": "101", "start": 0, "end": 1, "citation": "대법원 1991. 3. 8. 선고 90다16771 판결", "summary": "자동차보험약관상 고의에는 미필적 고의도 포함된다. 내심의 고의는 관련 간접사실을 논리와 경험칙에 따라 종합해 증명할 수 있다.", "pages": [79], "sourceHash": "164e31bce019808518b870e4cca223f38e4118843e651fdeb58755d794e78013"}], "민법4_강의자료(불법행위)-29": [{"key": "102", "start": 0, "end": 1, "citation": "대법원 2002. 7. 12. 선고 2001다46440 판결", "summary": "불법행위의 고의에는 위법한 결과가 생긴다는 사실의 인식이 있으면 된다. 그 결과가 법적으로 위법하다는 평가까지 알 필요는 없다.", "pages": [80], "sourceHash": "bd909157787566f6df9f8288b78ef5155e810236663f63b2a63f83d937395d02"}], "민법4_강의자료(불법행위)-30": [{"key": "103", "start": 0, "end": 2, "citation": "대법원 2001. 3. 9. 선고 2000다67020 판결", "summary": "사람이 보닛에 매달린 상태에서 지그재그로 운전해 떨어뜨린 경우 상해에 대한 미필적 고의가 인정된다. 보험약관의 고의 면책에도 미필적 고의가 포함된다.", "pages": [80], "sourceHash": "8d7474498d9b39471a94de424f3ace5b1f36f449dc7dd349c1aa4a8d4714bb1c"}], "민법4_강의자료(불법행위)-32": [{"key": "104", "start": 0, "end": 2, "citation": "대법원 1998. 10. 23. 선고 98다31479 판결", "summary": "주차장 운영자가 차량의 보관·감시의무를 부담하는지는 약정과 제공한 서비스, 거래통념 등을 보아야 한다. 단순히 주차장소를 제공하고 사용료를 받았다는 이유만으로 도난방지의무가 생기지는 않는다.", "pages": [80], "sourceHash": "27c3e408a3cb41b0e73154b68e5afa504b0523bfb765517879e14254ff25f7b9"}], "민법4_강의자료(불법행위)-37": [{"key": "105", "start": 0, "end": 1, "citation": "대법원 2001. 1. 19. 선고 2000다12532 판결", "summary": "불법행위의 과실은 사회평균인의 주의를 기준으로 한다. 여기서 평균인은 막연한 일반인이 아니라 구체적인 상황에서의 보통인을 뜻한다.", "pages": [81], "sourceHash": "771b34df38c8e5fa218b15aaec600ab887de70034be9240b3ebf78e300d1945a"}], "민법4_강의자료(불법행위)-38": [{"key": "106", "start": 0, "end": 1, "citation": "대판 1994. 11. 25, 94다35107", "summary": "건조한 봄철 산불 경보가 계속된 상황에서 담배불을 끄지 않고 잡초에 버린 행위에 화재 발생의 중대한 과실을 인정했다.", "pages": [81], "sourceHash": "6a04162b0794efcc30cd690d981b60ca4700523e33c9675b4c603890142276e8"}], "민법4_강의자료(불법행위)-39": [{"key": "107", "start": 0, "end": 2, "citation": "대법원 2003. 10. 23. 선고 2001다48057 판결", "summary": "하천 관리의 특수성과 예측·회피 가능성을 고려해야 한다. 계획홍수위를 크게 초과한 이례적인 폭우로 인한 범람은 불가항력으로 관리청의 책임이 부정될 수 있다.", "pages": [81, 82], "sourceHash": "581625558c1d02e1561d5ea43382e47e5f3a4fd6865e9dcc08881c95e59b15a9"}], "민법4_강의자료(불법행위)-40": [{"key": "108", "start": 0, "end": 1, "citation": "대법원 1998. 6. 12. 선고 98다14252, 14269 판결", "summary": "녹색신호로 진행하는 운전자는 특별한 사정이 없으면 다른 차량의 신호 준수를 신뢰할 수 있다. 다만 신호 변경 전에 이미 교차로에 진입한 차량의 동태는 살펴야 한다.", "pages": [82], "sourceHash": "c32d8be741a2fbd697907e7e73356cb0b68a5f5ee529244dd7953a5d7a935e8f"}], "민법4_강의자료(불법행위)-41": [{"key": "109", "start": 0, "end": 2, "citation": "대법원 2003. 4. 11. 선고 2003다3607,3614 판결", "summary": "갓길의 오토바이가 갑자기 차 앞으로 끼어들 것까지 예상할 의무는 없다. 위험을 발견한 뒤에도 충돌을 피할 수 없었다면 운전자의 과실을 인정하기 어렵다.", "pages": [82, 83], "sourceHash": "cf53c6d9186ba8d15081c255e2d015a48f5465d2484dcc1062bc7070ea942a68"}], "민법4_강의자료(불법행위)-44": [{"key": "110", "start": 0, "end": 1, "citation": "대판 1978. 11. 28, 78다1805", "summary": "만 14세 2개월의 중학생이 위험한 맨바닥에서 장난하다 상해를 가한 이 사건에서는, 나이와 행위 상황만으로 불법행위의 책임능력을 인정하기 어렵다고 보았다.", "pages": [83, 84], "sourceHash": "6f36ce6166bdba064060653426777e41c1789af96d1837e3b7b20d3f6a972245"}], "민법4_강의자료(불법행위)-45": [{"key": "111", "start": 0, "end": 1, "citation": "대판 1978. 7. 11, 78다729", "summary": "만 13세 5개월의 중학생이 고무총으로 돌을 쏘아 다른 아이를 실명시킨 경우, 불법행위의 책임을 인식할 능력이 있다고 단정하기 어렵다.", "pages": [84], "sourceHash": "c5150a5a27a75eaf47629ef752ab43681a0b664e2e651c4cc486b85c9a9821b5"}], "민법4_강의자료(불법행위)-53": [{"key": "112", "start": 0, "end": 2, "citation": "대법원 2021. 6. 30. 선고 2019다268061 판결", "summary": "불법행위의 위법성은 법률 위반에 한정되지 않고 전체 법질서와 사회통념에 따라 판단한다. 행위별로 침해 양태와 보호가치 있는 이익을 고려해야 한다.", "pages": [86], "sourceHash": "9941509965342d27c5811bbd1929480e76256aaebc6b5dda1ebf6732e11c4274"}], "민법4_강의자료(불법행위)-55": [{"key": "113", "start": 0, "end": 1, "citation": "대법원 2003. 3. 14. 선고 2000다32437 판결", "summary": "제3자의 채권침해가 언제나 불법행위는 아니다. 채권자를 해함을 알면서 법규·사회질서에 반하는 수단을 썼는지 등을 거래자유와 이익균형까지 고려해 판단한다.", "pages": [87], "sourceHash": "9f41aec3fa5efce97d050a5dcde20f82412340fed9f5d64f9f95693b38ff344a"}], "민법4_강의자료(불법행위)-56": [{"key": "114", "start": 0, "end": 1, "citation": "부당해고로 인한 불법행위책임(대판 1999. 2. 23, 98다12157)", "summary": "해고사유가 없음을 알거나 쉽게 알 수 있는데도 근로자를 내쫓으려 징계를 남용하는 등 사회통념상 명백히 부당한 해고는, 무효일 뿐 아니라 불법행위가 된다.", "pages": [87], "sourceHash": "e81f9a3ca17f023b2c1adc7090fb40f6e70614d9214bf0b2468017c59976b142"}, {"key": "114.2", "start": 1, "end": 2, "citation": "일조방해와 위법성(대판 2000. 5. 16, 98다56997)", "summary": "건축법규를 지켰더라도 일조방해가 사회통념상 수인한도를 넘으면 불법행위가 성립할 수 있다.", "pages": [87], "sourceHash": "b07133fe2aac8822463e06a835649e11eda09218bde5662095f4658e207a0a3a"}], "민법4_강의자료(불법행위)-57": [{"key": "115", "start": 0, "end": 3, "citation": "대법원 2002. 12. 10. 선고 2000다72213 판결", "summary": "일조방해의 위법성은 피해 정도, 지역성, 토지이용의 선후, 회피 가능성, 공법상 규제 등 모든 사정을 종합해 수인한도 초과 여부로 판단한다.", "pages": [87], "sourceHash": "254d0874ff6512f6aacc3b64d7619b63ac98f801ab1c61930718405450551069"}], "민법4_강의자료(불법행위)-58": [{"key": "116", "start": 0, "end": 2, "citation": "대법원 2021. 2. 25. 선고 2020다230239 판결", "summary": "고의·과실로 최고이자율을 넘는 이자를 받아 손해를 입히면 불법행위가 성립한다. 원본 충당 후 남는 초과액은 손해이며, 공동 가담자도 연대책임을 질 수 있다.", "pages": [87], "sourceHash": "0f01faeb5521059138a1a11518d72d8bd96676b0a5b5e010d7c7540f6f888885"}], "민법4_강의자료(불법행위)-59": [{"key": "117", "start": 0, "end": 1, "citation": "대법원 2021. 6. 30. 선고 2019다268061 판결", "summary": "계약교섭 과정에서 형성된 보호가치 있는 신뢰를 상당한 이유 없이 깨뜨리면 불법행위가 될 수 있다. 특히 상대방 성과물을 무단 이용한 경우 위법성이 인정되기 쉽다.", "pages": [87, 88], "sourceHash": "6aaba3384ff49d37dd8bf8bac8e632ecf55747bace2687121cb03f552645ed6c"}], "민법4_강의자료(불법행위)-61": [{"key": "118", "start": 0, "end": 2, "citation": "대법원 1992. 6. 23. 선고 91다33070 전원합의체 판결", "summary": "무효인 등기를 믿고 토지를 산 최종 매수인의 손해는 지급한 매매대금이다. 처음부터 소유권을 얻지 못했으므로 등기말소판결로 소유권을 잃은 것이 손해는 아니다.", "pages": [88], "sourceHash": "26b805cc3764b62af5dceb7363831405ba342da36263be9df8b6e90b87e76d8e"}], "민법4_강의자료(불법행위)-62": [{"key": "119", "start": 0, "end": 1, "citation": "대법원 1999. 6. 11. 선고 98다22857 판결", "summary": "장애를 갖고 출생한 사실 자체를 태어나지 않은 경우와 비교해 법적 손해라고 할 수 없다. 장애를 유발하지 않은 의사에게 아이 자신이 그 출생에 따른 비용을 청구할 수도 없다.", "pages": [88], "sourceHash": "71982461aab7b7eeda25b3ce12c3ebd9915edf796bdfc3027f6f750756781bb2"}], "민법4_강의자료(불법행위)-63": [{"key": "120", "start": 0, "end": 3, "citation": "대법원 2004. 4. 28. 선고 2001다36733 판결", "summary": "위법소득은 일실손해의 산정 기초가 될 수 없고, 위법성의 강도 등을 구체적으로 판단해야 한다. 애초 면허를 받을 수 없는 지역에서 한 무면허 어업의 수입은 제외된다.", "pages": [88], "sourceHash": "c082537d47898af4d1c13cd73ffd05d6f4c880854cdb81802aab471c2e42d153"}], "민법4_강의자료(불법행위)-64": [{"key": "121", "start": 0, "end": 2, "citation": "대법원 1992. 12. 8. 선고 92다34162 판결", "summary": "안전조치 없는 인접 공사로 일상의 평온이 깨지고 사고 불안에 시달린 정신적 고통은 재산상 배상만으로 회복되지 않을 수 있다. 그 경우 별도의 위자료를 인정할 수 있다.", "pages": [88, 89], "sourceHash": "c2b524b1744e0fb0ee1e5c35e062539f63de08a136d24a12e4e3e0aa4e3536b9"}], "민법4_강의자료(불법행위)-65": [{"key": "122", "start": 0, "end": 1, "citation": "대법원 2003. 4. 8. 선고 2000다53038 판결", "summary": "법원이 가압류결정을 송달하지 않았다는 사실만으로 채권액 전부의 손해가 생긴 것은 아니다. 다른 재산에서 회수할 수 없는 등 현실적 손해는 피해자가 증명해야 한다.", "pages": [89], "sourceHash": "52de28507f4e50ca10fee6d96cdccebb1426b791bca349c755a8296d955d743a"}], "민법4_강의자료(불법행위)-66": [{"key": "123", "start": 0, "end": 1, "citation": "대법원 2001. 4. 10. 선고 2000다46795 판결", "summary": "운송인이 선하증권과 상환하지 않고 물건을 다른 사람에게 인도해 소지인의 권리행사를 어렵게 했다면 곧바로 불법행위가 성립한다. 소지인이 소유권까지 잃을 필요는 없다.", "pages": [89], "sourceHash": "b4fb2c65baa0c7fabd0e43488b3a741e9df5fbf7363dd27f0221b5388d8ca4b7"}], "민법4_강의자료(불법행위)-68": [{"key": "124", "start": 0, "end": 4, "citation": "대법원 2001. 5. 8. 선고, 99다38699, 판결", "summary": "경쟁적 계약관계에서 기존 계약을 알면서 그에 반하는 계약을 맺었다는 사정만으로 제3자의 불법행위가 되지는 않는다. 적극 공모나 사회상규에 반하는 수단 등 특별한 사정이 필요하다.", "pages": [89, 90], "sourceHash": "7bafc2ee6a408dd62bfcf9c2e8a28f2079b5f9cd77f2dc68e275d2f4ac5943f5"}], "민법4_강의자료(불법행위)-69": [{"key": "125", "start": 0, "end": 2, "citation": "대법원 2006. 9. 8. 선고 2004다18859 판결", "summary": "공고된 입시요강대로 공정하게 심사받을 응시자의 신뢰는 보호된다. 학교 내부 학칙과 다르다는 이유만으로 이를 깨뜨리면 불법행위가 될 수 있다.", "pages": [90], "sourceHash": "f664170d5a5db6be037594f94a9095b58cd5dca27953ba6723273373f4923e08"}], "민법4_강의자료(불법행위)-70": [{"key": "126", "start": 0, "end": 1, "citation": "대법원 2006. 3. 9. 선고 2003재다262 판결", "summary": "사립학교 교원에게는 합리적 기준으로 공정하게 재임용심사를 받을 권리가 있다. 적법하게 심사했다면 재임용됐을 교원을 위법하게 거부한 경우 임금 상당의 배상을 청구할 수 있다.", "pages": [90], "sourceHash": "288c8c5c43c527ff719eaa5bb8c1a5780c086da1853509a1a87f2d263c30fddb"}], "민법4_강의자료(불법행위)-71": [{"key": "127", "start": 0, "end": 4, "citation": "대법원 2006. 10. 13. 선고 2004다16280 판결", "summary": "소송 증거를 모으기 위한 촬영이라도 초상권·사생활 침해가 당연히 정당화되지는 않는다. 장기간 미행·추적하며 몰래 촬영한 이 사건에서는 위법성 조각을 부정했다.", "pages": [90, 91], "sourceHash": "1cbfb3cc1e34071b25fe7381fafcfde0b2ec06875d6a4a8d354e546e4f73aaec"}], "민법4_강의자료(불법행위)-72": [{"key": "128", "start": 0, "end": 3, "citation": "대법원 2003. 11. 28. 선고 2003다43322 판결", "summary": "적법하게 건축한 건물이 민간방송의 전파송신을 방해했다는 이유만으로 불법행위가 되지는 않는다. 종전의 무상 송신 상태가 당연히 법적 보호이익이 되는 것은 아니다.", "pages": [91, 92], "sourceHash": "8473c3039093dfeecb1b4697f1855e7e481fc6e58c848b6f02548a55fea447c9"}], "민법4_강의자료(불법행위)-73": [{"key": "129", "start": 0, "end": 1, "citation": "대법원 2002. 5. 28. 선고 2000다5817 판결", "summary": "적법한 환지처분으로 채권자에게 간접적·경제적 손해가 생겼더라도, 청산금을 줄이려는 조합장 등의 의도만으로 불법행위가 성립하지는 않는다.", "pages": [92], "sourceHash": "64d90aca177ca36d860974c2ad93963f5808db55dd84e207d8ae0ac1731034af"}], "민법4_강의자료(불법행위)-74": [{"key": "130", "start": 0, "end": 2, "citation": "대법원 1995. 9. 5. 선고 94다30867 판결", "summary": "상가 업종보호 약정은 조합에 실질적인 보호조치 의무를 지운다. 다만 다른 수분양자의 임대행위가 기존 약정상 권리를 침해했다고 해서 곧바로 제3자의 불법행위가 되지는 않는다.", "pages": [92], "sourceHash": "82f8488e9024d52aeba515066ba148300cea3e45e1182f987d22bc6574ad0ae5"}], "민법4_강의자료(불법행위)-75": [{"key": "131", "start": 0, "end": 1, "citation": "대법원 1977. 8. 23. 선고 77다686 판결", "summary": "민사상 인과관계는 엄밀한 과학적 인과관계와 같지 않다. 예방접종 후 사망에 의학적 가능성이 있고 다른 원인을 인정할 자료가 없다면 법적 인과관계를 인정할 수 있다.", "pages": [92], "sourceHash": "3b8deb2219d9851f3170aeee3591d722487dc810bc8c5d9be8a32beaf95cbe76"}], "민법4_강의자료(불법행위)-76": [{"key": "132", "start": 0, "end": 1, "citation": "대법원 2022. 9. 16. 선고 2017다247589 판결", "summary": "상당인과관계는 결과 발생의 개연성뿐 아니라 주의의무 규범의 목적·보호법익, 가해행위의 모습, 침해이익과 피해 정도를 종합해 판단한다.", "pages": [92], "sourceHash": "ecb0341bfd0803b4b56aae2ebd20d33bda409b0ebb5d59bb0c56f294748f2106"}], "민법4_강의자료(불법행위)-77": [{"key": "133", "start": 0, "end": 1, "citation": "대법원 1997. 4. 11. 선고 97다3118 판결", "summary": "중앙분리대를 충격해 생긴 파편이 반대차선 사고를 일으킬 가능성은 예견할 수 있다. 파편을 만든 운전과 후속 사고 사이의 상당인과관계를 인정했다.", "pages": [93], "sourceHash": "33ef8cf1d0a3815f53a08f198808ff871e15a47d3d6818b56a1690f95d0dfab4"}], "민법4_강의자료(불법행위)-78": [{"key": "134", "start": 0, "end": 1, "citation": "대법원 1999. 7. 9. 선고 99다12796 판결", "summary": "앞차의 바퀴에 튕긴 도로 위 철판으로 뒤차 승객이 다친 이 사건에서는, 앞차의 과속과 피해 사이의 상당인과관계를 부정했다.", "pages": [93], "sourceHash": "37d86c77ab6db966cec989dd59863522171be003872d52e02abcfc971ea62969"}], "민법4_강의자료(불법행위)-79": [{"key": "135", "start": 0, "end": 4, "citation": "대법원 2010. 6. 10. 선고 2010다15363,15370 판결", "summary": "이사회결의 없이 부동산을 판 불법행위와, 매수인이 제기한 별도 소송에 대응하느라 지출한 변호사비용 사이에는 상당인과관계가 인정되기 어렵다.", "pages": [93], "sourceHash": "788fef65a766315335adbcab4acd3b27a3ec422db03ee8bb62010f10cec60930"}], "민법4_강의자료(불법행위)-80": [{"key": "136", "start": 0, "end": 1, "citation": "대법원 2007. 1. 11. 선고 2005다28082 판결", "summary": "분식회계가 없었으면 기업어음 여신을 제공하지 않았을 경우, 이후 정책적 고려로 회전매입을 결정했더라도 감사인의 과실과 손해 사이의 인과관계가 끊어지지는 않는다.", "pages": [93], "sourceHash": "8449ccc707b0385c0c7a1ef16b65257e0b0e225769e0bd5847fbddd418820122"}], "민법4_강의자료(불법행위)-81": [{"key": "137", "start": 0, "end": 1, "citation": "대법원 2005. 12. 9. 선고 2003다9742 판결", "summary": "적법하게 행동했어도 같은 손해가 났을 것이라는 주장만으로 쉽게 면책되지 않는다. 엄격한 절차나 자기결정권을 보호하는 규범인지, 같은 결과가 명백히 예상되는지 등을 보아야 한다.", "pages": [93], "sourceHash": "190aa34ea1a3dc0dfeb40f9415a261b3d32366b042e973931c0f5fe0aea5e5ed"}], "민법4_강의자료(불법행위)-83": [{"key": "138", "start": 0, "end": 1, "citation": "대판 2000. 9. 8, 99다48245", "summary": "환자 측이 상식에 기초한 의료상 과실과 다른 원인의 개재 가능성 없음을 증명하면, 의료진이 다른 원인을 증명하지 못하는 한 과실과 결과 사이의 인과관계를 추정할 수 있다.", "pages": [94], "sourceHash": "31a95cd797ee5a9fa3315553361bffcb29398c2f40417da709632998bacd172e"}], "민법4_강의자료(불법행위)-84": [{"key": "139", "start": 0, "end": 3, "citation": "대판 1984. 6. 12, 81다558", "summary": "공장 폐수의 배출, 양식장 도달, 이후 피해가 모순 없이 증명되면 인과관계가 일응 증명된다. 가해기업은 물질이 무해하거나 안전농도였다는 등의 반증으로 이를 깨야 한다.", "pages": [94], "sourceHash": "e562689c8330a1410f83d45ef5909834195b4f23d1083dfedd01a8e1e7af31ab"}], "민법4_강의자료(불법행위)-85": [{"key": "140", "start": 0, "end": 1, "citation": "대법원 2013. 7. 12. 선고 2006다17539 판결", "summary": "비특이성 질환은 위험인자 노출과 발병 사실만으로 인과관계가 증명되지 않는다. 역학조사와 개인의 노출 정도·건강상태·발병 경위 등을 추가로 증명해야 한다.", "pages": [94], "sourceHash": "8ac9aab048ee3dc9ccc2246319f83e779887e520ece4eb5174a6bd03c6f9d756"}], "민법4_강의자료(불법행위)-86": [{"key": "141", "start": 0, "end": 4, "citation": "대법원 1991. 7. 23. 선고 89다카1275 판결", "summary": "오염물질의 도달과 피해가 증명되면 기업은 무해함을 반증해야 한다. 배출기준 이내라도 수인한도를 넘으면 책임질 수 있고, 자연력이 함께 작용했다면 그 기여분을 고려해 배상범위를 제한한다.", "pages": [94], "sourceHash": "a07fc437b72de174399e542b8b99c4b3efae96a0190e235f3ec762edfaa2abc7"}], "민법4_강의자료(불법행위)-87": [{"key": "142", "start": 0, "end": 1, "citation": "대법원 2013. 7. 12. 선고 2006다17539 판결", "summary": "불법행위의 인과관계는 존재 여부를 판단해야 한다. 불확실성을 이유로 인과관계 자체를 일정 비율로 인정하는 이론은 받아들일 수 없다.", "pages": [95], "sourceHash": "a56065400f75356e34aa3ec8a143aa828a9361dee7411c5b90ff5e9abfdcbeac"}], "민법4_강의자료(불법행위)-88": [{"key": "143", "start": 0, "end": 1, "citation": "대법원 2008. 10. 9. 선고 2006다53146", "summary": "법인의 명예·신용이 훼손되면 재산상 손해 외의 무형적 손해도 배상 대상이 된다. 사실 적시뿐 아니라 저가 유사제품 유통 등으로 신용을 해치는 행위도 포함될 수 있다.", "pages": [96], "sourceHash": "9771a858f9c322ad9fa94b452c05314c39d42cb2438689e1fe2a637f1158a8cf"}], "민법4_강의자료(불법행위)-90": [{"key": "144", "start": 0, "end": 1, "citation": "대판 1967. 9. 5, 67다1307", "summary": "민법 제752조는 위자료청구권자를 제한하는 규정이 아니라 정신적 고통의 증명부담을 덜어 주는 규정이다. 열거된 사람 외의 친족도 위자료를 청구할 수 있다.", "pages": [97], "sourceHash": "3f21267447a631be6d1bc1f00438e34861f20968c1b6060c1dba953d04e39d46"}], "민법4_강의자료(불법행위)-91": [{"key": "145", "start": 0, "end": 1, "citation": "대법원 1978. 1. 17. 선고 77다1942 판결", "summary": "열거된 친족 외에도 정신적 고통을 증명하면 위자료를 청구할 수 있다. 사망 피해자의 직계비속의 배우자에게도 그 청구를 인정했다.", "pages": [97], "sourceHash": "90b418f4914f5cfb23697b26f48f893248b48925c6d720776c442a488a92c91c"}], "민법4_강의자료(불법행위)-92": [{"key": "146", "start": 0, "end": 1, "citation": "대법원 1999. 4. 23. 선고, 98다41377, 판결", "summary": "사망이 아닌 불법행위에서도 피해자의 부모는 자신의 정신적 고통을 증명해 위자료를 청구할 수 있다.", "pages": [97], "sourceHash": "7ec2a809cfc6dbd4c3e01125440f363b626c058878ea57bc98a4fc432872d6bf"}], "민법4_강의자료(불법행위)-94": [{"key": "147", "start": 0, "end": 1, "citation": "대법원 1993. 4. 27., 93다4663 판결", "summary": "사고 당시 태아였더라도 이후 출생했다면 아버지의 부상으로 인한 자신의 정신적 고통에 대해 위자료를 청구할 수 있다.", "pages": [97], "sourceHash": "b4498db5f8b550924d10724f38d349b37dd8a929cb1759cec20fa61900e6cd3d"}], "민법4_강의자료(불법행위)-95": [{"key": "148", "start": 0, "end": 1, "citation": "대법원 1967. 5. 23. 선고 66다1025 판결", "summary": "위자료청구권은 피해자가 생전에 청구 의사를 표시하지 않았더라도 원칙적으로 상속된다. 포기 등 특별한 사정이 있는 경우는 제외된다.", "pages": [97], "sourceHash": "edc23eb7700b5f8c7d94906e6c4f9dc25d29b96a28a0a04277d946717e14c8a5"}], "민법4_강의자료(불법행위)-100": [{"key": "149", "start": 0, "end": 3, "citation": "대법원 2014. 1. 16. 선고 2011다108057 판결", "summary": "위자료 액수는 사실심의 재량이지만 자의적으로 정할 수는 없다. 배상요건을 갖추지 못한 재산상 손해를 위자료로 대신 보전해서도 안 된다.", "pages": [98], "sourceHash": "7f05030e48b046b40718f3c122646280e08543d02e6e73ae0a99aa95cd4bed27"}], "민법4_강의자료(불법행위)-101": [{"key": "150", "start": 0, "end": 3, "citation": "대법원 2025. 7. 3. 선고 2025다200813 판결", "summary": "독성물질 노출만으로 정신적 손해가 추정되지는 않지만, 질병이 아직 없어도 노출 정도·유해성 등을 종합해 객관적으로 정신적 고통이 인정되면 위자료를 받을 수 있다.", "pages": [98, 99], "sourceHash": "eea66bbf6f3022c2214a19bc1f0d3c1420172991a2663aa8f42afd18e456ce63"}], "민법4_강의자료(불법행위)-102": [{"key": "151", "start": 0, "end": 2, "citation": "대법원 2017. 5. 17. 선고 2016다248806 판결", "summary": "자동차의 주요 골격이 파손되는 중대한 사고에서는 수리 후에도 원상회복되지 않는 부분이 남을 수 있다. 그에 따른 가격 하락도 통상손해로 배상 대상이 된다.", "pages": [99], "sourceHash": "b438ab91d6407a09c19b9197c3d8d7bf71d121cf9ce26f21ceea91ba793188c9"}], "민법4_강의자료(불법행위)-103": [{"key": "152", "start": 0, "end": 3, "citation": "대법원 2001. 11. 13. 선고 2001다26774 판결", "summary": "부당한 처분금지가처분으로 분양용 부동산의 처분이 늦어진 경우, 특별한 사정이 없으면 지연기간의 처분대금에 대한 법정이자 상당액은 통상손해다.", "pages": [99], "sourceHash": "6ca4629518b12da25c6d0b95e095e5a0ad623248cde06612c62d19d047921006"}], "민법4_강의자료(불법행위)-104": [{"key": "153", "start": 0, "end": 1, "citation": "대법원 2022. 5. 26. 선고 2021다300791 판결", "summary": "통상손해는 그 유형의 가해행위에서 일반적으로 생기는 손해이고, 특별손해는 개별적 사정에 따른 손해다. 특별손해는 그 사정을 알았거나 알 수 있었을 때 배상한다.", "pages": [99], "sourceHash": "9da02019d128c6d7ea78bd9eb82d03c6508c18a56e5ef4e84f72191dbde789e8"}], "민법4_강의자료(불법행위)-105": [{"key": "154", "start": 0, "end": 1, "citation": "대법원 1999. 1. 26. 선고 97다39520 판결", "summary": "건물 훼손의 손해는 수리비나 교환가치 감소액 등으로 정한다. 수리비가 건물의 교환가치를 넘으면 원칙적으로 그 교환가치 범위로 제한한다.", "pages": [99, 100], "sourceHash": "dc082aea0bd669e51abaf5b5f02e1cdb38a847ddeb29b03767ffc6c8c02c7399"}], "민법4_강의자료(불법행위)-106": [{"key": "155", "start": 0, "end": 2, "citation": "대법원 1997. 11. 25. 선고 97다35771 판결", "summary": "위법한 등기말소로 근저당권이 소멸해 배당받지 못했다면 손해배상책임이 생긴다. 손해액은 담보부동산 가액과 채권최고액을 한도로 한 피담보채권액이다.", "pages": [100], "sourceHash": "77b26b900a72eb9351973805d92c0d6dcf40c80d97ab4a528c6745e047a0c1a7"}], "민법4_강의자료(불법행위)-108": [{"key": "156", "start": 0, "end": 2, "citation": "대법원 2002. 10. 25. 선고 2002다42322 판결", "summary": "공매통지는 체납자가 세금을 내고 소유권을 지킬 기회도 보호한다. 따라서 적법한 통지 없이 진행한 공매와 소유권 상실 사이의 인과관계를 부정해서는 안 된다.", "pages": [100], "sourceHash": "0ae970fb3cb760c6bb1474c00333a26eb7831489aa546d9f08bd54b4f908d50a"}], "민법4_강의자료(불법행위)-109": [{"key": "157", "start": 0, "end": 4, "citation": "대법원 2006. 2. 24. 선고 2005다29207 판결", "summary": "공무원의 의무가 개인의 안전·이익도 보호한다면 그 위반에 국가배상책임이 생길 수 있다. 잘못 발급한 토지이용계획확인서가 거래 판단의 기초가 되는 경우도 포함된다.", "pages": [100, 101], "sourceHash": "34b782f1e4578095a17076914568399c1f6068db8f8f7c6816ada851828d7dbc"}], "민법4_강의자료(불법행위)-110": [{"key": "158", "start": 0, "end": 2, "citation": "대법원 2006. 9. 22. 선고 2005다30610 판결", "summary": "일반 조합원이 지시에 따라 단순히 노무를 중단했다는 이유만으로 공동책임을 지지는 않는다. 다만 위험한 공정을 멈추는 안전절차를 위반해 손해를 발생·확대시켰다면 책임질 수 있다.", "pages": [101], "sourceHash": "cfefb1e55a115bc267084902c773dfbb595fef97fa3dec2c7c3a10e86971bf5e"}], "민법4_강의자료(불법행위)-111": [{"key": "159", "start": 0, "end": 2, "citation": "대법원 1996. 1. 26. 선고 94다5472 판결", "summary": "전주 충격으로 정전돼 생긴 공장의 간접손해는 특별손해다. 가동 중인 기계·자재의 손상은 예견할 수 있지만 단순 영업이익 감소까지 당연히 예견되는 것은 아니다.", "pages": [101], "sourceHash": "d17ee3ddbb12551f981032dd557e206afd784dab63c0671b2d4f4d74d9f74cc3"}], "민법4_강의자료(불법행위)-112": [{"key": "160", "start": 0, "end": 5, "citation": "대법원 1997. 10. 10. 선고 96다52311 판결", "summary": "충돌 뒤 전선이 떨어져 공장에 화재가 난 손해는 이 사건에서 예견하기 어려운 간접손해로 보았다. 전주·변압기의 설치·보존 하자도 인정하지 않았다.", "pages": [101, 102], "sourceHash": "c97a0498d8982d9f9264a41021c6be5f3edd4a1b09307fe95bd0961d07156351"}], "민법4_강의자료(불법행위)-116": [{"key": "161", "start": 0, "end": 1, "citation": "대법원 1995. 6. 9. 선고 94다30515 판결", "summary": "피해자는 원칙적으로 일시금과 정기금 배상 중 선택할 수 있다. 다만 여명·장애기간 확정이 어려워 일시금이 현저히 불합리하다면 법원이 정기금 지급을 명할 수 있다.", "pages": [102], "sourceHash": "ecd7233777b5f5a74dca5027830f6ef2cf46f0709f645482f9446d66ef356d01"}], "민법4_강의자료(불법행위)-119": [{"key": "162", "start": 0, "end": 3, "citation": "헌법재판소 1991. 4. 1, 89헌마160 [전합]", "summary": "가해자에게 사죄광고를 강제하는 것은 양심의 자유와 인격권을 침해한다. 민법 제764조에 따른 명예회복처분에 사죄광고를 포함시키는 해석은 헌법에 위반된다.", "pages": [102, 103], "sourceHash": "8475ddcd5b0065270645b588055898ec12185192e49a166ca01cdbdd7d4f1e50"}], "민법4_강의자료(불법행위)-122": [{"key": "163", "start": 0, "end": 2, "citation": "대법원 2010. 8. 25. 자, 2008마1541 결정", "summary": "경쟁자의 투자·노력으로 만든 성과를 부당하게 무단 이용하는 행위는 불법행위가 될 수 있다. 계속되는 침해에 금전배상만으로 부족하고 이익형량상 필요하다면 금지·예방도 청구할 수 있다.", "pages": [103], "sourceHash": "6dac231d7b0ae6b0d88d8dd930b70acd3f4240f44b158dd0e88702d12e1de65a"}], "민법4_강의자료(불법행위)-123": [{"key": "164", "start": 0, "end": 2, "citation": "대법원 2005. 1. 17. 자, 2003마1477 결정", "summary": "명예권을 침해당하면 침해의 금지·예방도 청구할 수 있다. 다만 언론보도의 사전금지는 표현내용의 진실성·공익성과 회복하기 어려운 중대한 손해 등을 엄격하게 심사해 예외적으로 허용된다.", "pages": [103, 104], "sourceHash": "5124729e3519fd494405e52129a9136bcee5b852fbca50a47698b99040c0de7c"}], "민법4_강의자료(불법행위)-124": [{"key": "165", "start": 0, "end": 1, "citation": "대법원 2021. 10. 14. 선고 2021다242154 판결", "summary": "일반 공중에게 열린 도로를 일상생활에 필요한 범위에서 통행할 자유는 보호된다. 특정인의 통행만 부당하게 막는 행위에는 방해배제·예방을 청구할 수 있다.", "pages": [104], "sourceHash": "f29b629da3ba7a7739242e6e6782ce1e3c872e2f74b0edf95969b6e2ed37c337"}], "민법4_강의자료(불법행위)-125": [{"key": "166", "start": 0, "end": 1, "citation": "대법원 1994. 2. 25. 선고 93다38444 판결", "summary": "장래손해의 현가는 원칙적으로 불법행위 시를 기준으로 하지만, 사실심 변론종결 전 이미 발생한 손해 전액과 그 발생 후의 지연손해금을 구하는 방식도 허용될 수 있다.", "pages": [104], "sourceHash": "f7c64205caa08a15f01da86fc5d6013540bb65f935977611a3a5306761fdbc65"}], "민법4_강의자료(불법행위)-126": [{"key": "167", "start": 0, "end": 1, "citation": "대법원 2007. 6. 1. 선고 2005다5843 판결", "summary": "재산상 손해는 인정되지만 증명곤란으로 금액을 확정할 수 없어 배상받지 못하는 사정은 위자료 증액에 참작할 수 있다.", "pages": [105], "sourceHash": "f8e7aef8af95f9b45deebde8685c79f438cea02b0ff3909b860e53e50a27f635"}], "민법4_강의자료(불법행위)-127": [{"key": "168", "start": 0, "end": 1, "citation": "대법원 1984. 11. 13. 선고 84다카722 판결", "summary": "손해액 확정이 불가능한 재산상 손해는 위자료의 보완적 기능으로 고려할 수 있다. 그러나 확정 가능한 재산손해를 편의상 위자료 명목으로 배상해서는 안 된다.", "pages": [105], "sourceHash": "8ea8a80e3fdd6918de3b4534e40211b48bfbdba5eccf1816a1d97f0d88e17f7b"}], "민법4_강의자료(불법행위)-128": [{"key": "169", "start": 0, "end": 1, "citation": "대법원 1976. 4. 13. 선고 75다396 판결", "summary": "일실수입은 객관적 자료로 사고 당시의 실제소득을 확정해 산정한다. 신고소득이 현저히 낮거나 다른 소득의 합리적 증거가 있다면 신고액만으로 제한할 수 없다.", "pages": [105], "sourceHash": "75ec4080e112ad208b97a014c6852898c33a0c4400fed1bce599e5487104933d"}], "민법4_강의자료(불법행위)-129": [{"key": "170", "start": 0, "end": 1, "citation": "대법원 1989. 12. 26. 선고 88다카6761 전원합의체 판결", "summary": "장래 임금상승이 객관적 자료로 상당히 확실하게 예측되면 일실수입에 반영한다. 이는 통상손해로서 가해자의 별도 예견 여부를 묻지 않는다.", "pages": [105], "sourceHash": "c40b24e282a7aa3f0464cef216447600ee5b12f52dc55c3a3651164689e5bebd"}], "민법4_강의자료(불법행위)-130": [{"key": "171", "start": 0, "end": 1, "citation": "대법원 1966. 10. 18. 선고 66다1635,1636 판결", "summary": "법률이 금지하는 성매매를 계속해 얻을 수입은 일실수입 산정의 기초로 삼을 수 없다.", "pages": [105], "sourceHash": "37ba47e217ad731acd6030f8870ae1a6a00de6da1f44787311589a7149dbff97"}], "민법4_강의자료(불법행위)-131": [{"key": "172", "start": 0, "end": 2, "citation": "대법원 2024. 4. 25. 선고 2020다271650 판결", "summary": "도시 일용근로자의 월 가동일수는 통계·근로조건 등을 종합해 판단해야 한다. 이 사건 사고 당시에는 특별한 사정 없이 월 20일을 초과해 인정하기 어렵다고 보았다.", "pages": [105], "sourceHash": "c5dc585c1673f7be36888b969b1916ca806d0de6b81f5087965bb641828f7790"}], "민법4_강의자료(불법행위)-132": [{"key": "173", "start": 0, "end": 4, "citation": "일실이익의 산정(대판 1997. 4. 25, 97다5367)", "summary": "실제소득의 신빙성 있는 증거가 없으면 유사 직종의 통계소득을 활용한다. 근무회사가 사고 후 폐업했다면 장래 전업 가능성과 예상소득을 심리해야 하며 곧바로 일반노동임금으로 낮출 수는 없다.", "pages": [105, 106], "sourceHash": "aa89e6c7e998f0537b652a6cf17f557b8894b33db91694e99f9b02b17f35bce5"}], "민법4_강의자료(불법행위)-133": [{"key": "174", "start": 0, "end": 2, "citation": "대판 1988. 3. 22, 87다카1958", "summary": "장애가 경미하고 신분보장으로 현재·장래의 수입 감소 가능성도 없는 경우에는 노동능력 일부 감퇴만을 이유로 일실수입 손해를 인정할 수 없다.", "pages": [106], "sourceHash": "cdcc688b24371f204997a786591529d0aa457f6f761f0fc95a38facc36b5dca1"}], "민법4_강의자료(불법행위)-134": [{"key": "175", "start": 0, "end": 4, "citation": "대판 1991. 6. 11, 91다7385", "summary": "노동능력상실률은 신체장애율 자체가 아니라 나이·직업·숙련도·전업 가능성 등을 종합한 경제적 평가다. 프로야구 투수에게 일용노동자의 장애율을 그대로 적용해서는 안 된다.", "pages": [106, 107], "sourceHash": "bcf9b24ffd2abbb415bf7375e6e6c3ea3a9d6b3cf57b3328d268c912255bd0d6"}], "민법4_강의자료(불법행위)-135": [{"key": "176", "start": 0, "end": 2, "citation": "대판 1995. 11. 7, 93다41587", "summary": "고문치사 사실을 모르던 유족이 민·형사상 문제를 제기하지 않기로 하고 돈을 받았더라도 손해배상청구권을 포기한 것으로 볼 수 없다. 그 돈도 배상액에서 공제하지 않는다.", "pages": [107], "sourceHash": "ad37407ff13c5ec81528765b7571812848de3d7dd84c90f1ba4cdbcd6674d665"}], "민법4_강의자료(불법행위)-136": [{"key": "177", "start": 0, "end": 1, "citation": "대판 1991. 12. 13, 91다30057", "summary": "사고 후 합의의 효력은 당시 예측할 수 있었던 손해에 미친다. 소액 합의 당시 예상하지 못했던 중대한 후유장애 손해에는 부제소합의의 효력이 미치지 않을 수 있다.", "pages": [107, 108], "sourceHash": "1a4a257830e4d5005954aebffdb4cb2e1ecad2110033ace4d60820d519df697a"}], "민법4_강의자료(불법행위)-137": [{"key": "178", "start": 0, "end": 2, "citation": "대법원 1998. 8. 21. 선고 98다23232 판결", "summary": "운전자의 과실을 동승자 측 과실로 보려면 신분·생활관계상 일체성 등 구체적인 사정이 있어야 한다. 다방 주인 차에 업무상 동승한 종업원에게 그 과실을 돌리지 않은 사례다.", "pages": [108], "sourceHash": "375a8e13d32b7fa544b1bf9a92dc0bdaa48568daa093d32e70ca54a4ab956e1d"}], "민법4_강의자료(불법행위)-138": [{"key": "179", "start": 0, "end": 2, "citation": "대법원 1992. 11. 13. 선고 92다14687 판결", "summary": "과실상계에서 피해자의 과실은 가해자의 의무위반보다 약한 의미의 부주의다. 비율 판단은 현저히 불합리하지 않은 한 사실심의 권한에 속한다.", "pages": [108], "sourceHash": "814add42a4043b55af333f7275d6e05b8c63d1aaa6bafcbc439f91bb412b70f9"}], "민법4_강의자료(불법행위)-139": [{"key": "180", "start": 0, "end": 1, "citation": "대법원 2007. 10. 25. 선고 2006다16758,16765 판결", "summary": "피해자의 부주의를 이용한 고의의 영득행위에서는 책임제한으로 부당한 이익을 남겨 줘서는 안 된다. 다만 그런 결과가 없는 고의 불법행위까지 모든 책임제한이 금지되는 것은 아니다.", "pages": [108], "sourceHash": "87db292b92a6249f97cb53a80422345e4ecce9c248c9526d3c4826540699fc20"}], "민법4_강의자료(불법행위)-140": [{"key": "181", "start": 0, "end": 1, "citation": "대법원 1990. 5. 8. 선고 89다카29129 판결", "summary": "피해자 과실과 손해로 인한 이익이 함께 있다면, 먼저 과실상계를 하고 그 다음 손익상계로 이익을 공제한다.", "pages": [108], "sourceHash": "90275a336df94945540b788df8f5aa97822338389f85da2e670f05e23af3cb3d"}], "민법4_강의자료(불법행위)-141": [{"key": "182", "start": 0, "end": 3, "citation": "대법원 1992. 12. 22. 선고 92다31361 판결", "summary": "사고 뒤 같은 급여를 받더라도 합리적으로 평가한 노동능력상실에 따른 손해가 없다고 단정할 수 없다. 계속 근로해 받은 급여도 사고와 인과관계 있는 이익이 아니므로 배상액에서 공제하지 않는다.", "pages": [108], "sourceHash": "2678f743ec1b61ac7ef259ae1d668162da6fca4c8cbce9a76a63c2c3b02a6025"}], "민법4_강의자료(불법행위)-142": [{"key": "183", "start": 0, "end": 1, "citation": "대법원 2015. 11. 27. 선고 2011다28939 판결", "summary": "의료과실로 신체기능을 회복 불가능하게 손상시킨 뒤 악화 방지 등을 위해 한 치료에는 병원이 수술비·치료비를 청구할 수 없다. 공평상 배상책임을 일부 제한한 경우도 같다.", "pages": [108, 109], "sourceHash": "55b96bbe790161039bc912f2f8abeaacddb1bc8d2fac6e9d1d966ac02d777635"}], "민법4_강의자료(불법행위)-145": [{"key": "184", "start": 0, "end": 1, "citation": "대법원 1996. 12. 19. 선고 94다22927 전원합의체 판결", "summary": "민법 제766조 제2항의 10년과 수록된 예산회계법상의 5년은 모두 제척기간이 아니라 소멸시효기간이다.", "pages": [109], "sourceHash": "aceb0c02020fea993e9965a612ff552f5a2f8513a4d0c4b087c20110d182d599"}], "민법4_강의자료(불법행위)-146": [{"key": "185", "start": 0, "end": 2, "citation": "대법원 1998. 7. 24, 97므18 판결", "summary": "단기소멸시효는 피해자가 손해·위법행위·인과관계를 현실적이고 구체적으로 안 때부터 진행한다. 이 사건에서는 사실혼 존속확인소송 패소 전까지 그 인식을 인정하기 어렵다고 보았다.", "pages": [109, 110], "sourceHash": "608cd34bd8d76429654aba8cf181b0373700b150a50ef38f2365dfbc56e600c0"}], "민법4_강의자료(불법행위)-147": [{"key": "186", "start": 0, "end": 3, "citation": "대법원 2013. 7. 12. 선고 2006다17539 판결", "summary": "고엽제 피해의 인과관계를 확인하기 어려웠던 사정 아래 상당한 기간 내 권리를 행사했다면 시효항변이 권리남용이 될 수 있다. 그러나 등록 후 3년이 지나 제소한 일부 피해자에게는 이를 인정하지 않았다.", "pages": [110], "sourceHash": "8c8d35f80138a02993e31583d017b933688dd6643a8193c481698a0b7b1b61ee"}], "민법4_강의자료(불법행위)-148": [{"key": "187", "start": 0, "end": 3, "citation": "대법원 2001. 9. 4., 선고, 2001다9496, 판결", "summary": "합의 당시 예상하지 못한 중대한 후발손해에는 청구포기의 효력이 미치지 않을 수 있다. 새로 발생·확대된 손해의 단기시효는 그 사유가 판명된 때부터 진행한다.", "pages": [110, 111], "sourceHash": "ed5a1c28a26649e69d1e4f8894db35cf1da623b12929560e0a68cb3b04766665"}, {"key": "187.2", "start": 3, "end": 8, "citation": "[제766조 제3항 신설 이전 판결] 대법원 2021. 8. 19 선고 2019다297137 판결", "summary": "장기소멸시효도 손해가 객관적·구체적으로 현실화된 때부터 진행한다. 아동기 성폭력 뒤 성인이 되어 발현된 PTSD의 경우 전문가 진단 때 손해가 현실화됐다고 본 사례다.", "pages": [111], "sourceHash": "003707210ed62155db3e47d5d7a799469f29463ad5bc94ea805e9f62c61abc8a"}], "민법4_강의자료(불법행위)-149": [{"key": "188", "start": 0, "end": 1, "citation": "대법원 1998. 11. 10. 선고 98다34126 판결", "summary": "법인 대표가 불법행위에 가담했다면 그 대표의 인식만으로 단기시효가 시작되지 않는다. 법인의 이익을 지킬 다른 임원·직원 등이 청구할 수 있을 정도로 안 때부터 진행한다.", "pages": [111], "sourceHash": "8527937f1012e4b4c1563091929b80f7ce1fcc36a057ed1589cc4f77b882ea73"}], "민법4_강의자료(불법행위)-150": [{"key": "189", "start": 0, "end": 1, "citation": "대법원 2019. 8. 29. 선고 2017다276679 판결", "summary": "장기소멸시효의 ‘불법행위를 한 날’은 가해일 자체가 아니라 현실적 손해가 발생한 날이다. 손해가 현실화됐다면 피해자가 이를 알았는지는 기산에 영향을 주지 않는다.", "pages": [111], "sourceHash": "386b4fdc8e187db881c0498b4206c21f871e9ad7f5591d8175e69ff5f071afd6"}], "민법4_강의자료(불법행위)-158": [{"key": "190", "start": 0, "end": 2, "citation": "대법원 1978. 11. 28. 선고 78다1805 판결", "summary": "만 14세 2개월의 가해자에게 이 사건 행위의 책임능력을 인정하지 않았다. 보호감독자인 아버지가 감독의무를 다했음을 증명하지 못했으므로 배상책임을 부담한다.", "pages": [114], "sourceHash": "551abbf48c3ff1d6a7b898da16cf6c32c912b4bb6e026197fa40279073a70bab"}], "민법4_강의자료(불법행위)-159": [{"key": "191", "start": 0, "end": 1, "citation": "대법원 2007. 4. 26. 선고 2005다24318 판결 등 다수의 판결", "summary": "교장·교사의 감독의무는 교육활동과 밀접한 생활관계에 미친다. 사고의 구체적 위험을 예견할 수 있었는지 등을 보아 의무위반을 판단한다.", "pages": [115], "sourceHash": "6077e15378b9525d56cc47f28942cef357972c5c457cf32718bbf6785dee039d"}], "민법4_강의자료(불법행위)-160": [{"key": "192", "start": 0, "end": 5, "citation": "대법원 2007. 4. 26. 선고 2005다24318 판결", "summary": "집단따돌림으로 초등학생이 자살한 사건에서, 교사들의 보호·감독의무 위반과 손해 사이의 인과관계를 인정해 지방자치단체의 국가배상책임을 인정했다.", "pages": [115], "sourceHash": "4758992fba646cb01a815e2d41f337a5d9f72923c47ded73918d759dc70ce121"}], "민법4_강의자료(불법행위)-161": [{"key": "193", "start": 0, "end": 2, "citation": "대법원 1997. 6. 27. 선고 97다15258 판결", "summary": "교육활동과 관련된 사고라도 교사가 구체적으로 예견할 수 없는 돌발적 사고라면 감독책임을 지지 않는다. 수업 전 아크릴판을 던져 급우를 다치게 한 이 사건에서 책임을 부정했다.", "pages": [115, 116], "sourceHash": "84221552eb98e725fea52ee108ca36a52ca684877743e582d87fe9b766d42492"}], "민법4_강의자료(불법행위)-162": [{"key": "194", "start": 0, "end": 1, "citation": "대법원 2008. 1. 17. 선고 2007다40437 판결", "summary": "학교 교사뿐 아니라 학원 운영자·교습자도 해당 학원에서 배우는 수강생을 보호·감독할 의무를 진다.", "pages": [116], "sourceHash": "7aa71422fbaf37a7a9aee01f0c95170234a9bc082a08b0e6d2fcf33c4b0c7e70"}], "민법4_강의자료(불법행위)-163": [{"key": "195", "start": 0, "end": 1, "citation": "대법원 2002. 12. 10. 선고 2000다55126 판결", "summary": "대학 내 감금·폭행 사망이 교육활동과 관련이 없고 대학이 예견할 수 없었다면, 대학 또는 국가의 감독책임을 인정하기 어렵다.", "pages": [116], "sourceHash": "49d8b6c7497be0feadb4ff27d62e42d8627ae882c66858b401da5db3d3a285f3"}], "민법4_강의자료(불법행위)-164": [{"key": "196", "start": 0, "end": 5, "citation": "대법원 2000. 4. 11. 선고 99다44205 판결", "summary": "쉬는 시간의 학생 폭행이 구체적으로 예견하기 어려운 돌발적·우연한 사고였다면 교사에게 보호·감독의무 위반의 책임을 물을 수 없다.", "pages": [116], "sourceHash": "497abf01975aab6a05b6572b46bf8e0893d51558f5207ce60693a052d169a647"}], "민법4_강의자료(불법행위)-165": [{"key": "197", "start": 0, "end": 1, "citation": "대법원 1997. 6. 13. 선고 96다44433 판결", "summary": "휴식시간도 교육활동과 밀접해 일반적 감독의무가 미친다. 다만 급우 사이의 이 사건 돌발적 폭행을 예견할 수 없었다면 담임교사의 책임은 없다.", "pages": [116], "sourceHash": "db463431e725682c75bae4949dfbf448e4878dedb273e3b5b484c7c08c7c04cf"}], "민법4_강의자료(불법행위)-166": [{"key": "198", "start": 0, "end": 3, "citation": "대법원 2007. 6. 15. 선고 2004다48775 판결", "summary": "수업시간에 기존 폭력관계의 구체적 위험이 실현돼 사고가 난 경우, 이를 막지 못한 보호·감독의무 위반에 책임이 인정될 수 있다.", "pages": [116, 117], "sourceHash": "16ce1f4327a9fd68160d54198a7ca3b36715d73f266c72b00dc6120d4b4d2799"}], "민법4_강의자료(불법행위)-167": [{"key": "199", "start": 0, "end": 1, "citation": "대법원 2002. 5. 10. 선고 2002다10585,10592 판결", "summary": "유치원 운영자의 단 한 번의 성추행을 막지 못했다는 사정만으로 이 사건 교사의 손해배상책임을 인정하지 않았다.", "pages": [117], "sourceHash": "1b845d3a05b9db357b58e04cd490da46df4d967f8113f7489d9aa74be2cdd9b5"}], "민법4_강의자료(불법행위)-168": [{"key": "200", "start": 0, "end": 5, "citation": "대법원 2021. 7. 29. 선고 2018다228486 판결", "summary": "정신질환자의 부모가 타인을 해칠 구체적 위험을 알았고 대비할 객관적 상황에 있었다면, 방화 등 돌발행동과 손해 확대를 막을 주의의무 위반으로 책임질 수 있다.", "pages": [117], "sourceHash": "bf94e5548bd17db00553ea1a61621c18bcf20276d0a150e46b6eefe2c7940d7a"}], "민법4_강의자료(불법행위)-169": [{"key": "201", "start": 0, "end": 3, "citation": "대법원 2007. 4. 26. 선고 2005다24318 판결", "summary": "부모의 감독은 미성년자의 생활 전반에, 교사의 감독은 교육활동과 밀접한 관계에 미친다. 학교폭력 자살에 양쪽 과실이 함께 작용했다면 부모와 지방자치단체가 공동책임을 질 수 있다.", "pages": [118], "sourceHash": "c87941e40afd1d6e6f597b2401be66958ec88408e7bd74a22ffe83240b9d6955"}], "민법4_강의자료(불법행위)-170": [{"key": "202", "start": 0, "end": 3, "citation": "대법원 1989. 1. 24. 선고 87다카2118 판결", "summary": "수록된 1989년 판결은 만 18세 고등학생에게 책임능력이 있다고 보아 그 오토바이 사고에 대한 부모의 책임을 부정했다.", "pages": [118, 119], "sourceHash": "9f282651afe36880d7c18ea98b631dfe8802dc9614a5d88b1ae997e80af6e6f2"}], "민법4_강의자료(불법행위)-171": [{"key": "203", "start": 0, "end": 2, "citation": "대법원 1994. 2. 8. 선고 93다13605 판결 전원합의체 판결", "summary": "책임능력 있는 미성년자의 부모도 자신의 감독의무 위반과 사고 사이에 상당인과관계가 있으면 민법 제750조의 책임을 진다. 그 위반과 인과관계는 피해자가 증명해야 한다.", "pages": [119], "sourceHash": "78cb151fa2ca1e0a9ef9d7c5f6e203aa6b6c0d201caeeb2b807f237b1001cb7c"}], "민법4_강의자료(불법행위)-173": [{"key": "204", "start": 0, "end": 3, "citation": "대법원 1997. 3. 28. 선고 96다15374 판결", "summary": "부모가 미성년 자녀의 무면허 운전을 방치했고 그것이 사고 원인이 됐다면, 자녀에게 책임능력이 있어도 부모 자신의 감독상 과실로 배상책임을 진다.", "pages": [119], "sourceHash": "2f49bec05bd75345e046f2ec2fe1a889f45e1461f0bd5afe5d2e54d4375901c9"}], "민법4_강의자료(불법행위)-174": [{"key": "205", "start": 0, "end": 4, "citation": "대법원 2022. 4. 14. 선고 2020다240021 판결", "summary": "비양육친도 실질적으로 공동양육에 준하는 감독을 했거나 자녀의 불법행위를 구체적으로 예견하고도 필요한 조치를 하지 않은 특별한 사정이 있으면 감독책임을 질 수 있다.", "pages": [119, 120], "sourceHash": "a1edbedbc16b1cfe95a198a797b3a6d85a6dafeccb0560c61cb15e80b9d789d6"}], "민법4_강의자료(불법행위)-178": [{"key": "206", "start": 0, "end": 1, "citation": "대법원 2009. 6. 11. 선고 2008다79500 판결", "summary": "피용자의 무권대리가 기망행위여서 사용자책임이 이미 성립했다면, 사용자가 나중에 그 무권대리를 추인했다는 이유만으로 책임이 없어지지 않는다.", "pages": [121], "sourceHash": "9de112f2ba5e2a75618ac00ee7587c70c254dbcb5c4c9cd5f68e5d5e3b7b7a3a"}], "민법4_강의자료(불법행위)-179": [{"key": "207", "start": 0, "end": 1, "citation": "대법원 2017. 4. 27. 선고 2016다271226 판결", "summary": "사용자의 피용자에 대한 손해배상·구상은 사업위험, 근로조건, 예방조치 등을 고려해 신의칙상 상당한 범위로 제한된다. 사용자의 보험자가 구상하는 경우도 같다.", "pages": [121], "sourceHash": "62abf6107a138505e2b5a0db149173b8b253fcd2331faf249f23e944c51b0731"}], "민법4_강의자료(불법행위)-180": [{"key": "208", "start": 0, "end": 1, "citation": "대법원 2005. 1. 27. 선고 2004다12394 판결", "summary": "독립된 영업용 보세창고업자는 운송인의 의무이행을 보조하더라도 통상 그 지휘·감독을 받는 피용자는 아니다. 특별한 사정이 없으면 운송인에게 사용자책임을 물을 수 없다.", "pages": [122], "sourceHash": "a0cffde9fed9f3bef4a92e875386980bc2aba96d1adc83a4470b9a04bcf55ab4"}], "민법4_강의자료(불법행위)-181": [{"key": "209", "start": 0, "end": 1, "citation": "대법원 1981. 8. 11. 선고 81다298 판결", "summary": "교사에게 대리감독자책임이 있다는 이유만으로 그 사용자에게 사용자책임이 당연히 생기지는 않는다. 교사 자신의 고의·과실 등 일반 불법행위 요건이 별도로 충족돼야 한다.", "pages": [122], "sourceHash": "3bc3334fff9b98ed33044d4a36b0abf07f1636958a8f2850ea38e51733479697"}], "민법4_강의자료(불법행위)-182": [{"key": "210", "start": 0, "end": 3, "citation": "대법원 1998. 8. 21. 선고 97다13702 판결", "summary": "유효한 고용계약이 없어도 실질적 지휘·감독관계가 있으면 사용관계가 된다. 선장의 안전관리업무와 관련해 운송회사 외에 해운조합의 사용자책임도 인정했다.", "pages": [123], "sourceHash": "e094fe7dd672e7b21b7c996a372b845656480cd9fa980b97eff245e8d1184897"}], "민법4_강의자료(불법행위)-183": [{"key": "211", "start": 0, "end": 1, "citation": "대법원 2003. 12. 26. 선고 2003다49542 판결", "summary": "사실상 지휘·감독관계가 있으면 사용관계가 인정된다. 사무집행 관련성은 행위의 외형과 직무 관련성, 사용자의 위험 창출·방지조치 등을 고려해 판단한다.", "pages": [123], "sourceHash": "e6def622036f7dbcd13b5304ebcdb6a7d28d5285f22d1068593bcc0ffbd6e6d2"}], "민법4_강의자료(불법행위)-184": [{"key": "212", "start": 0, "end": 3, "citation": "대법원 1996. 10. 11. 선고 96다30182 판결", "summary": "고용계약이 없어도 장기간 이삿짐센터의 운반업무에 종사하며 지휘·감독을 받았다면 사용자책임에서 말하는 피용자가 될 수 있다.", "pages": [123], "sourceHash": "8c51efeae9d6e0a649a2a0cc61b4a4927f899d8f42b1641ffcee5b2f58a9f81d"}], "민법4_강의자료(불법행위)-185": [{"key": "213", "start": 0, "end": 2, "citation": "대법원 1999. 10. 12. 선고 98다62671 판결", "summary": "다른 기관이 위촉해 지휘하는 코치 업무 중 사고가 났다면, 기존 소속 대학의 신분을 유지했다는 이유만으로 국가를 그 업무의 사용자라고 할 수 없다.", "pages": [123], "sourceHash": "8c1412bd0aef0da74af3b423a6a914dd545d1ce81af1dc06901f3d3b324425d6"}], "민법4_강의자료(불법행위)-186": [{"key": "214", "start": 0, "end": 3, "citation": "대법원 2003. 10. 9. 선고 2001다24655 판결", "summary": "파견근로자가 사용사업주의 지시를 받더라도 파견사업주의 일반적 지휘·감독이 남아 있을 수 있다. 그 지위와 위험방지 책임에 따라 파견사업주도 사용자책임을 질 수 있다.", "pages": [123, 124], "sourceHash": "02da45085a24d434d12c8dfef2f006f341eaefcdf49c66aa863a911d932de0ef"}], "민법4_강의자료(불법행위)-187": [{"key": "215", "start": 0, "end": 3, "citation": "대법원 1998. 4. 28. 선고 96다25500 판결", "summary": "위임관계에서도 실질적 지휘·감독이 있고 불법행위가 외형상 위임사무와 관련되면 사용자책임이 생긴다. 장기간 재산관리 등을 맡긴 변호사의 기망행위에 적용한 사례다.", "pages": [124], "sourceHash": "dcf74481cee6bbf6dd4c493422db6b1adf150730819a691629fdbf207d52b8b2"}], "민법4_강의자료(불법행위)-188": [{"key": "216", "start": 0, "end": 1, "citation": "대법원 2001. 9. 4. 선고 2000다26128 판결", "summary": "퇴직 후에는 특별히 실질적 지휘·감독관계가 계속됐다는 사정이 없는 한 종전 사용자에게 사용자책임을 물을 수 없다.", "pages": [124], "sourceHash": "d204fde9fc2be6e7a5b0eee6faf2c33a61582ccecc28a9a1f103c4ad8733e1d8"}], "민법4_강의자료(불법행위)-190": [{"key": "217", "start": 0, "end": 1, "citation": "대법원 2005. 11. 10. 선고 2004다37676 판결", "summary": "도급인은 원칙적으로 독립된 수급인의 불법행위에 사용자책임을 지지 않는다. 그러나 특정 작업을 지휘하는 노무도급 등 실질적 지휘·감독관계에서는 책임질 수 있다.", "pages": [124], "sourceHash": "4d2106db79fb5bc84722bf9da1a0e8f8449777dad35f84852414693ca5420bad"}], "민법4_강의자료(불법행위)-191": [{"key": "218", "start": 0, "end": 1, "citation": "대법원 2001. 3. 9. 선고 2000다66119 판결(공 2001, 844)", "summary": "퇴직한 사람이 여전히 회사 업무를 하는 듯한 외관을 회사가 묵인했다면, 그가 고객 돈을 인출한 행위에 회사의 사용자책임이 인정될 수 있다.", "pages": [125], "sourceHash": "1dd704124067f084ef714e9ea3741015efc2672f907915425916ec907b59f799"}], "민법4_강의자료(불법행위)-192": [{"key": "219", "start": 0, "end": 1, "citation": "대법원 2007. 6. 28. 선고 2007다26929 판결(미간행)", "summary": "사업 명의 사용을 허락한 사람은 실제 지휘 여부와 별개로 객관적·규범적으로 감독해야 할 지위에 있다면, 명의차용자의 업무상 불법행위에 사용자책임을 진다.", "pages": [125], "sourceHash": "ebec10bb8515586de9fddfae109d67e5e939330e2cc3106cc76d135c50827b42"}], "민법4_강의자료(불법행위)-193": [{"key": "220", "start": 0, "end": 1, "citation": "대판 2006. 3. 10, 2005다65562", "summary": "동업자 중 한 사람에게 공동업무 집행을 맡겼다면 다른 동업자도 그 업무집행자에 대한 사용자의 지위에 있다. 집행 중 사고에 사용자책임을 질 수 있다.", "pages": [125], "sourceHash": "2f69c689fa7400a9ccbc0e73d7d8598d00a242479826beaf28c0a1fbfa144948"}], "민법4_강의자료(불법행위)-194": [{"key": "221", "start": 0, "end": 1, "citation": "대판 2001. 8. 21, 2001다3658", "summary": "타인에게 사업 명의 사용을 허락해 외부에 자기 사업·종업원으로 보이게 했다면, 그 업무 중 발생한 고의·과실의 손해에 사용자책임을 진다.", "pages": [125], "sourceHash": "bcbae5c633f2c51350655d0aaa6c1abd49a5c8803b5d1cae9c424b8424cc34a7"}], "민법4_강의자료(불법행위)-195": [{"key": "222", "start": 0, "end": 2, "citation": "대법원 1998. 2. 10. 선고, 95다39533 판결", "summary": "사용자책임의 사무집행 관련성은 객관적 외형으로 판단한다. 이 사건에서는 직무와 무관하게 은밀히 이뤄져 사용자가 알 수 없었던 성희롱에 고용계약상 보호의무 위반도 부정했다.", "pages": [125, 126], "sourceHash": "0bf6d131b5e1e7f9a594969d268c9a0ac0c8516410ec2ee3b596a185c1667da4"}], "민법4_강의자료(불법행위)-196": [{"key": "223", "start": 0, "end": 1, "citation": "대법원 2003. 2. 11. 선고, 2002다62029 판결", "summary": "피용자의 행위가 직무집행이 아님을 피해자가 알았거나 거의 고의에 가까운 중과실로 몰랐다면, 외관이 있더라도 사용자책임을 물을 수 없다.", "pages": [126], "sourceHash": "9474dee62bd453403aec30c646a40632aba038cf45e99106fb45007b15018eb1"}], "민법4_강의자료(불법행위)-197": [{"key": "224", "start": 0, "end": 1, "citation": "대법원 1995. 2. 3. 선고 94다43115 판결", "summary": "세무사 사무장이 세금 신고·납부 대행을 맡아 돈을 편취한 행위는 외형상 세무사의 사무집행과 밀접하다. 세무사에게 그 손해의 사용자책임을 인정했다.", "pages": [126], "sourceHash": "2db37b0289a3e746d975759f662a43f8e75d08c5f106f54d86d0e71ddf9ea081"}], "민법4_강의자료(불법행위)-198": [{"key": "225", "start": 0, "end": 1, "citation": "대법원 2021. 3. 11. 선고 2018다285106 판결", "summary": "가해행위가 직무 자체는 아니어도 시간·장소, 업무수행 과정이나 동기가 사업과 관련되면 사무집행 관련성이 인정될 수 있다. 위험방지 조치도 함께 고려한다.", "pages": [126], "sourceHash": "52076caae58a0e54f7644664c087e222163a0a9bab0d9fb1848a82c66d74bd65"}], "민법4_강의자료(불법행위)-199": [{"key": "226", "start": 0, "end": 1, "citation": "대법원 1993. 5. 27. 선고 92다48109 판결", "summary": "도급인이 작업 진행·방법에 구체적인 지휘·감독권을 유보했다면 실질적 사용관계가 된다. 하도급의 경우에도 수급인 측 불법행위에 사용자책임을 질 수 있다.", "pages": [126], "sourceHash": "a7bc372c58f236942be22b1c3eb1e33ffa30ac3eb240dc777b89ca6e510fe7db"}], "민법4_강의자료(불법행위)-200": [{"key": "227", "start": 0, "end": 1, "citation": "대법원 2000. 2. 11. 선고 99다47297 판결", "summary": "호텔 직원이 근무 중 고객과 업무 문제로 다투다 상해를 가했다면 사무집행 관련성이 인정된다. 접객업소의 고객 대응 교육·감독 필요성도 고려한다.", "pages": [126, 127], "sourceHash": "e3b6936a0bc87b848bb09f6306932e3165e48047e80c6169bd632506054c61ce"}], "민법4_강의자료(불법행위)-201": [{"key": "228", "start": 0, "end": 1, "citation": "대법원 1997. 10. 10. 선고 97다16572 판결", "summary": "작업 중 물을 달라는 사람에게 농약을 음료로 오인해 준 행위도 본래 업무와 밀접한 부수행위로 볼 수 있어 회사의 사용자책임이 인정된다.", "pages": [127], "sourceHash": "4711eabd187ac32d560594e7a9b7d35c866943c70ebb0b4cbb08c361f766d784"}], "민법4_강의자료(불법행위)-202": [{"key": "229", "start": 0, "end": 2, "citation": "대법원 1994. 11. 18. 선고, 94다34272 판결", "summary": "영업시간·사업장 안의 행위라도 개인적 폭행에 대항해 저지른 살해가 직무와 무관했다면 사무집행 관련성은 인정되지 않는다.", "pages": [127], "sourceHash": "401f511064ac569f8cc078686459846d27b31fb35e4f6c7f9f9bd465d27c1335"}], "민법4_강의자료(불법행위)-203": [{"key": "230", "start": 0, "end": 1, "citation": "대법원 2005. 12. 23. 선고 2003다30159 판결", "summary": "피용자의 차용·인출이 사용자의 업무가 아님을 은행 지점장이 알고 응했다면, 은행은 그 손해에 관해 사용자책임을 물을 수 없다.", "pages": [127], "sourceHash": "eb6e9118a54386712ae224dd4d8da2270b7218b63a724875ad878aedce6dbed5"}], "민법4_강의자료(불법행위)-204": [{"key": "231", "start": 0, "end": 3, "citation": "대법원 1992. 3. 31. 선고, 91다39849 판결", "summary": "운전수와 함께 차량을 일시 임대한 경우 기존 회사와 임차인 모두 사용자의 지위에 있을 수 있다. 각 책임은 부진정연대이고 구상범위는 과실에 따른 부담부분으로 정한다.", "pages": [128], "sourceHash": "9622568d160290d999f745230c2038367aed48793afc5285c3d41c5cc5c6ccae"}], "민법4_강의자료(불법행위)-205": [{"key": "232", "start": 0, "end": 3, "citation": "대법원 1994. 12. 13. 선고 94다17246 판결", "summary": "사용자의 업무지시, 인력·설비 부족 등 사업위험을 고려하면 피용자에 대한 구상권이 신의칙상 제한될 수 있다. 이 사건 곤돌라 사고에서는 직원들에 대한 구상을 부정했다.", "pages": [128, 129], "sourceHash": "390dff1971631ef4513c89861b391e4332fe8865287e715f9b9662c51926b715"}], "민법4_강의자료(불법행위)-206": [{"key": "233", "start": 0, "end": 2, "citation": "대법원 1991. 5. 10. 선고 91다7255 판결", "summary": "사용자는 피용자의 업무상 사고에 대해 사업규모·근로조건·예방조치 등 제반 사정을 고려한 신의칙상 상당한 한도에서만 손해배상이나 구상을 청구할 수 있다.", "pages": [129], "sourceHash": "3df8c089b88fc714a3c1bc48799fd752dd9f3c24b811da29c3b35b55d6ba6fef"}], "민법4_강의자료(불법행위)-208": [{"key": "234", "start": 0, "end": 1, "citation": "대법원 1996. 11. 22. 선고 96다39219 판결", "summary": "공작물 점유자·소유자의 책임 규정은 시공자 자신의 시공상 고의·과실에 대한 일반 불법행위책임을 배제하지 않는다.", "pages": [130], "sourceHash": "a3f5de4f1bb45795db4bcc8029628734d5b4b91f79379f78b753e48ee4a5db4c"}], "민법4_강의자료(불법행위)-209": [{"key": "235", "start": 0, "end": 1, "citation": "대법원 2026. 1. 8. 선고 2022다233713 판결", "summary": "공작물 소유자의 무과실책임도 손해의 공평한 분담이라는 취지에서 이해해야 한다. 피해자 과실은 가해자 과실보다 약한 부주의로서 배상액 산정에 참작할 수 있다.", "pages": [130], "sourceHash": "b0abdcd709bbd2672c4e008387dc4a26df492bab2fa47ac86b7e78f403394a45"}], "민법4_강의자료(불법행위)-210": [{"key": "236", "start": 0, "end": 1, "citation": "대법원 1993. 3. 9. 선고 92다54715 판결", "summary": "차량 차단시설 사이에 목 높이의 쇠사슬을 연결해 통행자가 걸려 사망한 경우, 그 시설의 설치·보존 하자를 인정했다.", "pages": [130], "sourceHash": "fcc055279cb8049bb502e12960f37c941eeef280f2419d97555efaeb9f20faa5"}], "민법4_강의자료(불법행위)-211": [{"key": "237", "start": 0, "end": 2, "citation": "대법원 1998. 1. 23. 선고 97다25118 판결", "summary": "공작물은 용도에 맞는 통상적 안전성을 갖추면 된다. 보호벽 위로 올라가 내부를 엿보는 부정행위까지 예상해 별도 방호조치를 할 의무는 없다고 본 사례다.", "pages": [130, 131], "sourceHash": "4ce0448aee506505062319beb6bdd482cddcafee8d32588e25d186dacba8b911"}], "민법4_강의자료(불법행위)-212": [{"key": "238", "start": 0, "end": 2, "citation": "대법원 1994. 10. 28. 선고 94다16328 판결", "summary": "도시가스처럼 고도의 위험을 지닌 시설이 법령상 시설기준에 맞지 않으면 특별한 사정이 없는 한 공작물의 하자에 해당한다.", "pages": [131], "sourceHash": "25680d790ebdcf98f6798c3e33ebda5589085b64ec03c260aa0f0109926cd3c4"}], "민법4_강의자료(불법행위)-213": [{"key": "239", "start": 0, "end": 1, "citation": "대법원 2000. 1. 14. 선고 99다39548 판결", "summary": "온풍기 연통을 불이 붙기 쉬운 천막지붕에 가깝게 설치한 것은 설치·보존상의 하자다.", "pages": [131], "sourceHash": "955faffb02089f92ec5d8df0200092db3e6dc492a6e8a840f5d379294ecda519"}], "민법4_강의자료(불법행위)-214": [{"key": "240", "start": 0, "end": 2, "citation": "대법원 1988. 11. 8. 선고 86다카775 판결", "summary": "고속도로 추월선에 큰 차단블록이 나온 상태는 통상적 안전성이 부족한 보존상 하자다. 하자가 인정된 뒤에는 관리자가 불가항력이나 필요한 주의를 다했음을 증명해야 면책된다.", "pages": [131], "sourceHash": "204a9f969650fac4a98e48aa33983cb03cb6645e154a38e04ea332d58b1dfc82"}, {"key": "240.2", "start": 2, "end": 4, "citation": "[하자의 개념에 관한 객관적 관점을 따르지 않은 판결] 대법원 1992. 9. 14. 선고 92다3243 판결", "summary": "제3자가 고속도로에 떨어뜨린 타이어가 있었다는 사실만으로 바로 하자를 인정할 수는 없다. 감시체계, 발견 가능성, 제거·복구할 시간과 조치 여부 등을 구체적으로 심리해야 한다.", "pages": [131], "sourceHash": "ebfe145ffdee6e9fe046c552ddddf1a11c8b92932cb7320c8c5b74de106ecd04"}], "민법4_강의자료(불법행위)-215": [{"key": "241", "start": 0, "end": 2, "citation": "대법원 1993. 6. 29. 선고 93다11913 판결", "summary": "전기 그 자체는 민법 제758조의 공작물이 아니다. 고압전선의 새를 잡으려다 감전된 이 사건에서는 단전조치 미실시와 피해 사이의 상당인과관계도 부정했다.", "pages": [131], "sourceHash": "6ac18d9176604bd37fe55848631bfe9a84e636d9b87b583a61b05fb637ae3f11"}], "민법4_강의자료(불법행위)-216": [{"key": "242", "start": 0, "end": 2, "citation": "대법원 2019. 11. 28. 선고 2017다14895 판결", "summary": "공작물 하자는 위험에 비례해 통상 필요한 안전조치를 했는지로 판단한다. 하자가 사고의 공동원인이라면 소유자·점유자가 하자 없이도 불가피했음을 증명하지 못하는 한 인과관계를 인정한다.", "pages": [131, 132], "sourceHash": "12bfaf04ebbfbf1623387208abbe4121c53c9b14c4e5a225c875025e687fda0a"}], "민법4_강의자료(불법행위)-217": [{"key": "243", "start": 0, "end": 1, "citation": "대법원 1977. 11. 8. 선고 77다1486 판결", "summary": "일반인의 출입이 금지된 역 구내 횡단로는 일반 통행용 건널목이 아니다. 무단 통행 중 사고에 건널목의 설치·보존 하자책임을 물을 수 없다.", "pages": [132], "sourceHash": "5991c8575ee307f5e4134167b72cf0ead6ae6b99520b32e88d9f4714c3fefc3b"}], "민법4_강의자료(불법행위)-218": [{"key": "244", "start": 0, "end": 2, "citation": "대법원 1992. 4. 24. 선고 91다37652 판결", "summary": "공작물에 완전무결한 안전까지 요구되지는 않는다. 위험을 아는 학생들이 출입 제한 옥상에서 위험행동을 할 것까지 예상해 상시 감시·난간을 설치할 의무는 없다고 보았다.", "pages": [132], "sourceHash": "21a5c65e164600fccbebe7ff3da22272b46c9ecc5265e949fbfd7cac70ad8dae"}], "민법4_강의자료(불법행위)-219": [{"key": "245", "start": 0, "end": 1, "citation": "대법원 1981. 6. 23. 선고 80다2993 판결", "summary": "놀이용 시설이 아니어도 주변 사정상 아이들이 올라가 놀 것이 예상되면 그에 맞는 안전관리를 해야 한다. 표시판 관리소홀에 점유자·소유자의 책임을 인정했다.", "pages": [132], "sourceHash": "443a309a490fef26400ce6f534def03f069f45c93d3f20c32fbf023cd7c5c527"}], "민법4_강의자료(불법행위)-220": [{"key": "246", "start": 0, "end": 2, "citation": "대법원 2000. 4. 21. 선고 2000다386 판결", "summary": "공작물점유자는 실제 지배와 함께 보수·관리할 권한·책임이 있는 사람이다. 담보가치 보전을 위해 공장 경비를 했다는 사실만으로 근저당권자가 점유자가 되지는 않는다.", "pages": [133], "sourceHash": "2f73163835bd25c438958775f436c3ac524192b4df614cc7d19db8ac1a9f3179"}], "민법4_강의자료(불법행위)-221": [{"key": "247", "start": 0, "end": 1, "citation": "대법원 2003. 2. 28. 선고 2002다65516 판결", "summary": "임차인이 외벽에 설치한 간판이 떨어진 경우에도 건물주는 외벽의 직접점유자로서 공작물책임을 질 수 있다.", "pages": [133], "sourceHash": "5e1ccb7ea8e630f2af3320c06b0eddb372901ed25f284fa6e67d52bcd744b61b"}], "민법4_강의자료(불법행위)-222": [{"key": "248", "start": 0, "end": 1, "citation": "대법원 1994. 7. 29. 선고 93다32453 판결", "summary": "LPG 사용신고자는 특별한 사정이 없으면 사용시설을 사실상 지배·관리하는 사람으로서 공작물점유자에 해당한다.", "pages": [133], "sourceHash": "8f1b37a87abf7d429df520c84c74278e22e35c140fedac123debb6495b01a72c"}], "민법4_강의자료(불법행위)-223": [{"key": "249", "start": 0, "end": 1, "citation": "대법원 1994. 6. 28. 선고 94다2787 판결", "summary": "가스 공급업자가 계량기의 보수·관리를 직접적·구체적으로 지배했다면 사용자와 함께 공작물점유자가 될 수 있다.", "pages": [133], "sourceHash": "850bca62732b9209205ce6955662684daef7a8530dd17b468e35becadfa5908b"}], "민법4_강의자료(불법행위)-224": [{"key": "250", "start": 0, "end": 3, "citation": "대법원 2024. 2. 15. 선고 2019다208724 판결", "summary": "공작물을 물리적으로 다룬다는 사실만으로 점유자책임을 지는 것은 아니다. 타인의 지시를 받아 지배하는 점유보조자는 민법 제758조의 책임주체가 아니다.", "pages": [133], "sourceHash": "45448bf19df9118adec9465b39b241614fc9c5e79aa0ed76764cacdf565cb8b8"}], "민법4_강의자료(불법행위)-225": [{"key": "251", "start": 0, "end": 2, "citation": "대법원 1993. 2. 9. 선고 92다31668 판결", "summary": "직접점유자인 임차인이나 그와 같은 지위의 사람이 공작물 하자로 피해를 입었다면 소유자에게 배상을 청구할 수 있다. 피해자의 보존상 과실은 과실상계 사유다.", "pages": [133], "sourceHash": "0a9bb1cea94758df2d3a12833d8030587daaeb2bd87534766c68cf15bcc8925e"}], "민법4_강의자료(불법행위)-226": [{"key": "252", "start": 0, "end": 1, "citation": "대법원 1987. 4. 14. 선고 86다카1705 판결", "summary": "임차인이 균열을 알리고 보수를 요구했는데 임대인이 수리를 미뤄 벽이 무너졌다면, 임차인은 필요한 주의를 다한 것으로 보아 소유자인 임대인이 책임진다.", "pages": [133], "sourceHash": "81c83cddd2763c2a4a973b54b97b83f0c9884158f38ec0b6968c364c025adf35"}], "민법4_강의자료(불법행위)-228": [{"key": "253", "start": 0, "end": 1, "citation": "대판 1981. 2. 10, 선고 80다2966 판결", "summary": "위험한 도사견을 빌려주는 소유자는 상대방에게 안전하게 보관·관리할 시설이 있는지 확인해야 한다. 동물의 간접점유자에게도 주의의무가 인정될 수 있다.", "pages": [134], "sourceHash": "416f1b72899b578cb4121a490597aa6e4537b0b73e594105045cbbc7e48361a5"}], "민법4_강의자료(불법행위)-233": [{"key": "254", "start": 0, "end": 1, "citation": "대법원 1997. 8. 29. 선고 96다46903 판결", "summary": "공동불법행위에는 공모나 공동 인식이 필수적이지 않다. 각 행위에 객관적 관련공동성이 있고 그로 인해 손해가 났다면 공동책임이 성립한다.", "pages": [136], "sourceHash": "2d1fc02042ee7c4a2ffa7b43aa119997c9a14cc65faea4cdc5348a217785dea1"}], "민법4_강의자료(불법행위)-234": [{"key": "255", "start": 0, "end": 1, "citation": "대법원 1998. 11. 24. 선고 98다32045 판결", "summary": "교통사고 치료 중 의료과실로 손해가 확대되면 의사의 중과실 등 특별한 사정이 없는 한 원래 사고와도 인과관계가 있다. 각 행위가 불법행위 요건과 객관적 관련성을 갖추면 공동책임을 진다.", "pages": [136], "sourceHash": "de4c68fc3ca8c10400f8b27fae9b1709b589ce0f45290dc91e93e49d96df318b"}], "민법4_강의자료(불법행위)-235": [{"key": "256", "start": 0, "end": 1, "citation": "대법원 1968. 2. 27. 선고 67다1975 판결", "summary": "각자의 공작물 하자책임이 객관적으로 같은 손해에 공동 작용했다면, 주관적 공모가 없어도 공동불법행위가 성립할 수 있다.", "pages": [136], "sourceHash": "292ee5642ac094d5f4b0e4052f5e6f4436596ae2d72db40f59f67ead1c1b8317"}], "민법4_강의자료(불법행위)-236": [{"key": "257", "start": 0, "end": 1, "citation": "대법원 1994. 11. 25. 선고, 94다35671, 판결", "summary": "교통사고와 후속 의료과실이 객관적으로 관련돼 손해를 확대시켰다면, 특별한 사정이 없는 한 두 가해자는 공동불법행위자로서 연대책임을 진다.", "pages": [136], "sourceHash": "5b3718255b71c13ba9a6bd5b9784864b39af432fcb181a1e0e1488dc648433e2"}], "민법4_강의자료(불법행위)-237": [{"key": "258", "start": 0, "end": 2, "citation": "대법원 1997. 11. 28. 선고, 97다18448", "summary": "싸움에 가세한 사람들 사이에 공모가 없어도 폭행의 객관적 관련공동성으로 손해가 발생했다면 공동불법행위책임을 피할 수 없다.", "pages": [136], "sourceHash": "3813077cd15b9b5f3eabff91d9dd249ff0b525bc7be6011dcab90195b990aa0d"}], "민법4_강의자료(불법행위)-238": [{"key": "259", "start": 0, "end": 2, "citation": "대법원 1993. 1. 26. 선고, 92다4871 판결", "summary": "교통사고 후 무리한 물리치료로 증상이 악화된 경우에도 원래 사고와 상당인과관계가 인정될 수 있다. 객관적 관련공동성이 있으면 운전자와 의사가 연대책임을 진다.", "pages": [136, 137], "sourceHash": "7c00813ff34ea2870a646f1da3ec72b7b39861c5b6070f957de791d71ee820bf"}], "민법4_강의자료(불법행위)-239": [{"key": "260", "start": 0, "end": 1, "citation": "대법원 1989. 5. 23. 선고 87다카2723 판결", "summary": "교통사고의 부상과 한 달 뒤 병원 추락사의 결과를 구별할 수 있다면 공동불법행위로 전 손해를 연대배상하게 할 수 없다. 각 행위로 생긴 손해를 구분해야 한다.", "pages": [137], "sourceHash": "18f8875614f7a880ffdb2615c9a6e1c1db76bef92f126771100249e274a98f60"}], "민법4_강의자료(불법행위)-240": [{"key": "261", "start": 0, "end": 2, "citation": "대법원 1998. 2. 13선고 96다7854 판결", "summary": "오염혈액 공급으로 인한 신체침해와 수혈 설명의무 위반으로 인한 자기결정권 침해는 결과를 구별할 수 있다. 이 경우 두 행위의 공동불법행위는 성립하지 않는다.", "pages": [137], "sourceHash": "535fe01c5dfa39935c2a7b5cee52d7e24341585e46e4f4ff21f894a84f23c16a"}], "민법4_강의자료(불법행위)-241": [{"key": "262", "start": 0, "end": 2, "citation": "대법원 2005. 9. 30. 선고 2004다52576 판결", "summary": "여러 의사 중 누구의 과실로 의료사고가 났는지 특정할 수 없으면 민법 제760조 제2항에 따라 관여 의사들 모두에게 공동책임을 물을 수 있다.", "pages": [137, 138], "sourceHash": "2867dae003a4b20596314f2df4fdcd4b6f433535af72e5f4fe317aa6d920a1ac"}], "민법4_강의자료(불법행위)-243": [{"key": "263", "start": 0, "end": 1, "citation": "대법원 2014. 3. 27. 선고 2013다91597 판결", "summary": "불법행위 방조는 작위뿐 아니라 의무 있는 사람의 부작위로도 성립한다. 과실 방조의 인과관계는 피해에 끼친 영향과 신뢰 형성, 피해자의 방지 가능성 등을 종합해 판단한다.", "pages": [138], "sourceHash": "79f03e27b2ef13d9852530042a0367a7a7ceabfa63e50e051b89a0eb8e3e361b"}], "민법4_강의자료(불법행위)-244": [{"key": "264", "start": 0, "end": 1, "citation": "대법원 2014. 1. 29. 선고 2011다107627 판결", "summary": "민사상 방조는 과실로도 가능하다. 다만 불법행위를 돕지 않을 주의의무의 위반이 있어야 하고, 방조와 본래 불법행위 사이에 상당인과관계도 필요하다.", "pages": [138], "sourceHash": "eba39dad65562bd62a731e14e99066bc7642c7f2e2a9daa4762f8f25ae51a7a0"}], "민법4_강의자료(불법행위)-245": [{"key": "265", "start": 0, "end": 3, "citation": "대판 2001. 5. 8., 2001다2181", "summary": "급여 외 소득이 없는 직원에게서 월급의 몇 배씩 계속 송금받으며 부정한 출처를 미필적으로나마 알았다면, 횡령의 방조 또는 장물취득이 될 수 있다.", "pages": [139], "sourceHash": "af3de9483c04a87fd8de8732543210dbf30bd4fe9873a3ba148c192f5f0a82b8"}], "민법4_강의자료(불법행위)-246": [{"key": "266", "start": 0, "end": 1, "citation": "대법원 2010. 3. 11. 선고 2009다4343 판결", "summary": "포털에 침해 게시물이 있다는 사실만으로 책임이 생기지는 않는다. 불법성을 알거나 명백히 알 수 있고 통제가 가능한데도 삭제·차단하지 않았다면 부작위 방조책임이 생길 수 있다.", "pages": [139], "sourceHash": "7a278c4008d2d5f0cc705bfd1f184ef33ac680c06636109e64baf2adf5a015d0"}, {"key": "266.2", "start": 1, "end": 2, "citation": "전주지법 2012. 5. 23. 선고 2011나9771 판결", "summary": "신원 불명자의 환치기를 돕는 행위가 범죄에 악용될 수 있음을 예견할 수 있었다면 보이스피싱의 과실 방조가 될 수 있다. 이 하급심은 피해자 사정도 고려해 책임을 30%로 제한했다.", "pages": [139], "sourceHash": "2fbf236024990f2fef1408371d74a73da21b0c59416b005380115a36d928c5f5"}], "민법4_강의자료(불법행위)-248": [{"key": "267", "start": 0, "end": 1, "citation": "대법원 2006. 2. 9. 선고 2005다28426 판결", "summary": "공동불법행위자는 자기 부담부분을 넘게 변제해 공동면책을 시키면 다른 가해자에게 구상할 수 있다. 피용자의 부담부분을 초과해 배상한 사용자도 제3자에게 구상할 수 있다.", "pages": [140], "sourceHash": "bcea44a14677e71406012c14f89d3a607425deee2b8fe18685389b173088bc85"}], "민법4_강의자료(불법행위)-250": [{"key": "268", "start": 0, "end": 1, "citation": "대법원 2010. 9. 16. 선고 2008다97218 전원합의체 판결", "summary": "부진정연대채무자 한 사람의 상계나 상계계약으로 채권이 만족되면, 소멸한 채무 전액에 관해 다른 채무자에게도 효력이 미친다.", "pages": [140], "sourceHash": "1e6999bca27ffa2c8e4f12b03f26c1898a248f2c1490b84271754fa524f18ec6"}], "민법4_강의자료(불법행위)-251": [{"key": "269", "start": 0, "end": 1, "citation": "대법원 2001. 9. 7. 선고 99다70365 판결", "summary": "공동불법행위자는 피해자에게 손해 전액을 배상할 책임이 있다. 다른 가해자보다 가담 정도가 작다는 이유로 피해자에 대한 책임을 자기 기여분으로 제한할 수 없다.", "pages": [140, 141], "sourceHash": "2222c4afea709f20e0d2f7834cef73a1ae831da5df2fb3003dc5774c606b05cc"}], "민법4_강의자료(불법행위)-252": [{"key": "270", "start": 0, "end": 2, "citation": "대법원 2001. 2. 9. 선고 2000다60227 판결", "summary": "공동가해자별로 별도 소송을 하면 증거에 따라 손해액·과실비율이 다를 수 있다. 먼저 받은 판결금이 후속 소송에서 인정된 손해에 못 미치면 다른 가해자에게 차액을 청구할 수 있다.", "pages": [141], "sourceHash": "3339c9634612f66f634dad78b9c9ed90be871a45dcf0bbd8e65deac1d1bb8626"}], "민법4_강의자료(불법행위)-253": [{"key": "271", "start": 0, "end": 3, "citation": "대법원 1997. 4. 11. 선고 97다3118 판결", "summary": "공동불법행위의 과실상계는 피해자의 과실을 가해자별로 따로 평가하지 않고 가해자 전원에 대한 관계에서 전체적으로 평가한다.", "pages": [141], "sourceHash": "3f85f705f79905c40bb9becb08849b178ad4d5dd0f8de4558cf5786507da01a5"}], "민법4_강의자료(불법행위)-254": [{"key": "272", "start": 0, "end": 3, "citation": "대법원 1998. 6. 12, 선고 96다55631 판결", "summary": "연속된 충돌로 공동불법행위가 성립한 경우에도 피해자 과실은 각 운전자에 대해 개별적으로 나누지 않고 전체적으로 평가한다.", "pages": [141, 142], "sourceHash": "4a52cfe87b1f333e68d9da7272026f4e46feec85bfa6e684e379f4c6dcf6bb8b"}], "민법4_강의자료(불법행위)-255": [{"key": "273", "start": 0, "end": 1, "citation": "대법원 2000. 9. 8. 선고 99다48245 판결", "summary": "시설 하자와 후속 의료과실이 함께 사망을 일으켰다면, 피해자 측 과실은 각 가해자의 과실과 따로 대비하지 않고 가해자 전원에 대해 전체적으로 평가한다.", "pages": [142], "sourceHash": "7bb0017717d22d9a8e0a9ff99afe5b83ae510e75b2e4be86997ecd46ceca0f28"}], "민법4_강의자료(불법행위)-256": [{"key": "274", "start": 0, "end": 3, "citation": "대법원 2007. 6. 14. 선고 2005다32999 판결", "summary": "고의 가해자가 피해자의 부주의를 이용했다고 해서 과실로 방조한 다른 가해자까지 과실상계를 주장할 수 없게 되는 것은 아니다.", "pages": [142], "sourceHash": "ed027414e606208e8f8407574285abc9906745b7101279cd603f8d5ecc9711d5"}], "민법4_강의자료(불법행위)-257": [{"key": "275", "start": 0, "end": 1, "citation": "대법원 2010. 2. 11. 선고 2009다68408 판결", "summary": "전체평가 원칙은 피해자 과실을 공동가해자 전원에 대해 평가하라는 뜻이다. 고의 가해자가 있다는 이유로 모든 가해자의 과실상계가 금지되는 것은 아니다.", "pages": [142], "sourceHash": "d6d717331815e2d81b8dc71f190e1e8e24064367b3750334d0f1120ca6f276e1"}], "민법4_강의자료(불법행위)-258": [{"key": "276", "start": 0, "end": 1, "citation": "대법원 2018. 3. 22. 선고 2012다74236 전원합의체 판결", "summary": "금액이 다른 부진정연대채무에서 다액채무자가 일부 변제하면, 먼저 그가 단독 부담하는 부분부터 소멸한다. 사용자의 과실상계로 배상액이 달라진 경우도 같다.", "pages": [142], "sourceHash": "a6c2b1b5da2917c41ef678c41f0af683be294e9d113c6cab09cfd77d5addc66b"}], "민법4_강의자료(불법행위)-260": [{"key": "277", "start": 0, "end": 4, "citation": "대법원 1997. 12. 12. 선고 96다50896 판결", "summary": "공동가해자가 자기 부담부분을 넘어 배상해 공동면책을 시키면 구상권이 생긴다. 한 채무자에 대한 피해자의 포기·면제는 다른 채무자에게 영향을 주지 않는다.", "pages": [143], "sourceHash": "8d5313d967b4325614f4ec4731294d36da32b1d4efcf9377a53d871fa34ab02d"}, {"key": "277.2", "start": 4, "end": 6, "citation": "구상권을 행사하는 공동불법행위자 측에 과실이 없는 경우 구상채무가 부진정연대관계에 있는지 여부(대판 2005. 10. 13, 2003다24147)", "summary": "여러 가해자의 구상채무는 원칙적으로 부담부분에 따른 분할채무다. 다만 구상권자 측의 내부 부담이 전혀 없다면 그에 대한 구상의무는 부진정연대관계가 된다.", "pages": [143], "sourceHash": "73be30b92cb27c3c711c8268b2db00ad8206e9468da746e2da314d0f09d107d5"}, {"key": "277.3", "start": 6, "end": 8, "citation": "공동불법행위에 대하여 민법 제426조의 적용여부(대판 1998. 6. 26, 98다5777)", "summary": "공동불법행위의 부진정연대채무에는 연대채무의 변제 전후 통지의무 규정을 유추하지 않는다. 따라서 그 통지가 구상권 행사의 요건은 아니다.", "pages": [143], "sourceHash": "cd09296e83af530800b80ac017cba87530f8a7eba23768506cbc99c4ef613171"}, {"key": "277.4", "start": 8, "end": 9, "citation": "공동불법행위자 중 1인에 대한 채무면제의 효력(대판 1969. 8. 26, 69다962)", "summary": "채굴작업과 사고책임을 수급인에게 모두 맡기는 도급계약을 맺어도 광업권자의 법령상 갱내 보안의무는 그대로 남는다.", "pages": [143], "sourceHash": "b966f103d2d670b4ce4e3f92a6a25d216e1d9bfeb320530a0d21f406d83dc6b9"}, {"key": "277.5", "start": 9, "end": 13, "citation": "구상권의 소멸시효(대판 1996. 3. 26, 96다3791)", "summary": "공동가해자의 구상권은 피해자의 배상채권과 별개다. 공동면책한 때부터 10년의 시효가 진행하며, 보험자대위로 취득해도 원래 구상권의 성질이 상사채권으로 바뀌지 않는다.", "pages": [144], "sourceHash": "5f64831f63da7ef4b7b3bef3305ac8df3dd8135d725710cbd4f08a7d827768a2"}], "민법4_강의자료(불법행위)-261": [{"key": "278", "start": 0, "end": 7, "citation": "대판 2001. 2. 15, 96다42420", "summary": "다수의견은 직무상 피해 군인 등에 대한 국가배상이 제한되는 경우, 민간인의 책임도 자기 부담부분으로 제한하고 국가에 대한 구상은 부정했다. 반대의견은 전액배상과 국가 구상을 인정해야 한다고 보았다.", "pages": [144, 145], "sourceHash": "00e55a4858879a2afe090cb5b68ab193970023e7601077da284dcdedd3b1136f"}], "민법4_강의자료(불법행위)-262": [{"key": "279", "start": 0, "end": 1, "citation": "대법원 2001. 1. 19. 선고 2000다33607 판결", "summary": "공동가해자 사이의 구상비율은 과실·손해 기여도뿐 아니라 특별한 내부 법률관계도 고려한다. 형평에 맞지 않으면 신의칙상 상당한 범위로 구상을 제한할 수 있다.", "pages": [145], "sourceHash": "1d69c1c8da8b22600dab160180aa3a140a97962263fe783390d3a5e01075da68"}], "민법4_강의자료(불법행위)-263": [{"key": "280", "start": 0, "end": 1, "citation": "대판 1988. 12. 13., 85다카1491 판결", "summary": "의사의 진료채무는 반드시 치유라는 결과를 내야 하는 채무가 아니라 적절한 진료조치를 다할 수단채무다. 나쁜 결과만으로 진료채무 불이행이 추정되지는 않는다.", "pages": [146], "sourceHash": "8e4e6b4b7f1c20aa63928d95b2568921ee55a55300c192c9055631a12a9a20c1"}], "민법4_강의자료(불법행위)-264": [{"key": "281", "start": 0, "end": 3, "citation": "대법원 1993. 7. 27., 92다15031 판결", "summary": "의료과실로 신체기능이 회복 불가능하게 손상된 뒤 후유증 치료만 이어졌다면, 병원은 그 수술비·치료비를 청구할 수 없다. 진료채무의 이행이나 별도의 유상진료로 보기 어렵기 때문이다.", "pages": [146, 147], "sourceHash": "298f6bf68a582dc16cfe541c2e5cfe4cc3f028bef5e6e3fa700f7a337141cbcd"}], "민법4_강의자료(불법행위)-265": [{"key": "282", "start": 0, "end": 2, "citation": "대법원 2018. 5. 11. 선고 2018도2844 판결", "summary": "의료과실은 결과를 예견·회피할 수 있었는지에 따라 판단한다. 적절한 치료가 어렵다면 전문 치료가 가능한 병원으로 신속히 옮기는 등 최선의 조치를 해야 한다.", "pages": [147], "sourceHash": "361df1916489ac62af98423236c4c9967eb732a907e6f961fc52ac639a3c844c"}], "민법4_강의자료(불법행위)-266": [{"key": "283", "start": 0, "end": 6, "citation": "대법원 2007. 5. 31., 2005다5867 판결", "summary": "검사과정의 과실이 인정되지 않고 설명의무 위반만 인정된다면, 손해배상을 사망으로 인한 전 손해가 아니라 자기결정권 침해의 위자료로 제한할 수 있다.", "pages": [147, 148], "sourceHash": "2c841c6d4a18d5b996e65480b125141807a019c9d1a1e62092d4602b1bd5bc29"}], "민법4_강의자료(불법행위)-267": [{"key": "284", "start": 0, "end": 3, "citation": "대법원 1987. 1. 20., 86다카1469 판결", "summary": "농촌 보건진료원의 주의의무를 의사의 수준과 동일하게 볼 수는 없다. 이 사건 주사 후 사망에서 일반 과실 가능성과 별개로 중과실 인정은 부정했다.", "pages": [148, 149], "sourceHash": "1153d41e1dad521e25d1cbe515719e7fc0f9b6cfae5c277dc5dbfd17658641ca"}], "민법4_강의자료(불법행위)-268": [{"key": "285", "start": 0, "end": 1, "citation": "대법원 1976. 12. 28., 74도816 판결", "summary": "이전 주사 뒤 발진·가려움 등 부작용을 들었다면 추가 조사와 투약 판단, 쇼크 대비 및 사후조치를 해야 한다. 반응검사를 반복할 의무가 없었다는 이유만으로 주의의무를 다한 것은 아니다.", "pages": [149], "sourceHash": "c3c837d46cb264326057a6d0c3f865ee8e7e2b64cb046115d05e7b328b14fe79"}], "민법4_강의자료(불법행위)-269": [{"key": "286", "start": 0, "end": 1, "citation": "대법원 1997. 5. 9., 97다1815 판결", "summary": "새 증상이 나타나면 기존 진단과 다른 질환도 의심해 정밀하게 살펴야 한다. 별다른 검사·투약 후 관찰 없이 약물을 투여해 쇼크 사망을 초래했다면 배상책임을 진다.", "pages": [149], "sourceHash": "7d94290b8dab74cb15649a47f936407e03a27c570c772a8ac251bb0406b34198"}], "민법4_강의자료(불법행위)-270": [{"key": "287", "start": 0, "end": 2, "citation": "대법원 2005. 6. 24., 2005다16713 판결", "summary": "응급수술이 필요한 환자를 잘못된 병원으로 옮기고 처치정보도 제공하지 않아 수술이 늦어졌다면 전원상 과실책임이 생긴다. 반면 수용 병원이 필요한 사항을 확인했다면 추가 질문 의무까지 당연히 생기지는 않는다.", "pages": [149], "sourceHash": "139b2578a3b8a88b758b0ce65e75e1461201b907eaa63d052208356bc0efb2f8"}], "민법4_강의자료(불법행위)-272": [{"key": "288", "start": 0, "end": 1, "citation": "대법원 2007. 5. 31., 2005다5867 판결", "summary": "환자가 치료의 필요성과 위험을 비교해 선택할 수 있도록 설명해야 한다. 전형적이거나 회복 불가능하게 중대한 부작용은 발생 가능성이 낮아도 설명 대상이다.", "pages": [150], "sourceHash": "e7cf05f3b9ce932467314c27c48d3c320dfc70dac20ceb782440beb707b26915"}], "민법4_강의자료(불법행위)-273": [{"key": "289", "start": 0, "end": 1, "citation": "대법원 2002. 1. 11., 2001다27449 판결", "summary": "투약도 신체에 대한 침습이므로 특별한 사정이 없으면 위험·부작용 등을 설명해 선택 기회를 줘야 한다. 치료상 과실이 없어도 무설명 투약은 위법할 수 있고 약사의 조제·판매에도 원칙적으로 적용된다.", "pages": [150], "sourceHash": "4ac9bad67e1b768e9ab029ddb0ecebaa3d6426c7206b59831c682d5f0f1bd708"}], "민법4_강의자료(불법행위)-274": [{"key": "290", "start": 0, "end": 6, "citation": "대법원 1998. 2. 13., 96다7854 판결", "summary": "오염혈액을 공급한 혈액원의 신체침해 책임과 수혈 위험을 설명하지 않은 의사의 자기결정권 침해 책임은 구별된다. 서로 다른 결과를 낳은 경우 공동불법행위가 성립하지 않는다.", "pages": [150, 151], "sourceHash": "703c04141d051f433042a5bf7ce3c1d226c41c8c378eb27c77ebcb9088857afa"}], "민법4_강의자료(불법행위)-275": [{"key": "291", "start": 0, "end": 1, "citation": "대법원 1994. 4. 15., 93다60953", "summary": "설명 부족으로 선택 기회를 잃은 데 대한 위자료는 그 상실을 증명하면 된다. 사망 등 전 손해를 청구하려면 설명의무 위반과 결과의 상당인과관계 및 의료상 과실에 준하는 정도의 위반이 필요하다.", "pages": [151], "sourceHash": "cd0b32dc78fa1b9ab855ab6c4033c780009fc2c2f768aa12895180ef66aad6e3"}], "민법4_강의자료(불법행위)-276": [{"key": "292", "start": 0, "end": 1, "citation": "대법원 2007. 5. 31., 2005다5867 판결", "summary": "설명을 했다는 문서 등을 남기기 쉬운 의사 측이, 특별한 사정이 없는 한 설명의무를 이행했음을 증명해야 한다.", "pages": [152], "sourceHash": "3125369d2ec1302cea32e9c8540269001224e137c5bc84b68fe33d8c6e84602d"}], "민법4_강의자료(불법행위)-277": [{"key": "293", "start": 0, "end": 2, "citation": "대법원 2020. 11. 26. 선고 2020다244511 판결", "summary": "의료상의 과실 외에 다른 원인이 없다는 간접사실로 과실·인과관계를 추정할 수 있다. 그러나 충분한 개연성 없이 중한 결과만으로 추정해 의사에게 무과실 증명책임을 넘겨서는 안 된다.", "pages": [152], "sourceHash": "5dab6a22ded48480dd6238a859751cab04710f3c0dc09cd1745a7fed3396f402"}], "민법4_강의자료(불법행위)-278": [{"key": "294", "start": 0, "end": 1, "citation": "대법원 2005. 9. 30. 선고 2004다52576 판결", "summary": "환자 측이 상식에 기초한 의료상 과실과 다른 원인의 개재 가능성 없음을 증명하면, 의료진이 다른 원인을 반증하지 못하는 한 인과관계를 추정할 수 있다.", "pages": [153], "sourceHash": "c2ae7fe98f34d4508b076457ba7a5bce597680f6eaf2cbf7219600fe8d84991d"}], "민법4_강의자료(불법행위)-279": [{"key": "295", "start": 0, "end": 1, "citation": "대법원 1995. 2. 10., 93다52402 판결", "summary": "의료행위의 전문성 때문에 환자에게 완벽한 의학적 증명을 요구할 수는 없다. 구체적인 과실과 다른 원인의 부재를 증명한 경우 의료과실과 결과의 인과관계를 추정한다.", "pages": [153], "sourceHash": "cef3552181c52aa969621514d965f8df3c65f3a347e92e5f1ff3f1bf4299e2be"}], "민법4_강의자료(불법행위)-280": [{"key": "296", "start": 0, "end": 1, "citation": "대법원 1996. 6. 11., 95다41079 판결", "summary": "전신마취·수술 중 심정지로 장애가 생긴 경우에도, 구체적 과실과 기존 건강결함 등 다른 원인의 부재가 증명되면 의료진의 반증이 없는 한 인과관계를 추정할 수 있다.", "pages": [153], "sourceHash": "3d193079f488a6c152f076f82d37003f9ed56eb9f8fa33dc5b9e10147642d283"}], "민법4_강의자료(불법행위)-281": [{"key": "297", "start": 0, "end": 2, "citation": "대법원 2023. 1. 12. 선고 2022도11163 판결", "summary": "형사 의료과오에서는 검사가 업무상 과실의 존재·내용을 구체적으로 증명해야 한다. 의료행위 후 나쁜 결과가 났거나 막연한 가능성이 있다는 이유만으로 과실을 추정할 수 없다.", "pages": [153], "sourceHash": "1c878557dc8d786194bfac2177281fd6d4435253c6401a5b6f56e8aeb42eeeb8"}], "민법4_강의자료(불법행위)-292": [{"key": "298", "start": 0, "end": 3, "citation": "대법원 2001. 2. 9, 99다55434 판결", "summary": "고속도로 소음·진동이 수인한도를 넘어 양돈장에 피해를 줬다면 책임이 인정될 수 있다. 수록된 환경정책기본법은 사업장 환경오염 피해에 귀책사유가 없어도 배상하도록 한다.", "pages": [155, 156], "sourceHash": "21c1cc24b45bd07ead932c432e18df63353a90702d5b8d8ff55803af49bf9f15"}], "민법4_강의자료(불법행위)-293": [{"key": "299", "start": 0, "end": 2, "citation": "대법원 1973. 10. 10., 73다1253 판결", "summary": "공장에 당시 기술상 가능한 방지시설을 갖췄다는 이유만으로 유해가스 피해에 과실이 없다고 단정할 수 없다.", "pages": [157], "sourceHash": "c531d89b368886be5fd40067aa6c99269cebcc8f5cb5a5d4fab96c9a8a24c0e3"}, {"key": "299.2", "start": 2, "end": 3, "citation": "부산지법 2012. 5. 10. 선고 2008가합21566 판결", "summary": "석면공장은 분진의 외부 비산과 인근 주민 노출을 막을 주의의무가 있다. 이 하급심은 지속적 노출로 주민들이 악성중피종 등에 걸려 사망한 데 대한 책임을 인정했다.", "pages": [157], "sourceHash": "e81cade566ae392181c058b401dfcf5d82f0163db7656093721e0986dbf67509"}], "민법4_강의자료(불법행위)-297": [{"key": "300", "start": 0, "end": 2, "citation": "대법원 2001. 6. 29. 선고 2001다23201, 23218 판결", "summary": "자배법상 운행자책임이 인정되지 않아도 민법상 불법행위책임은 가능하다. 열쇠를 꽂고 문도 잠그지 않은 차량의 절도운전 사고에 인과관계를 인정한 사례다.", "pages": [158], "sourceHash": "58e8ec05d5da0ed4d1aa89323ed5beb8533da51b247c4bca10c1c7ca54855dae"}], "민법4_강의자료(불법행위)-298": [{"key": "301", "start": 0, "end": 2, "citation": "대법원 1996. 3. 8. 선고 94다23876 판결", "summary": "공무원이 직무상 자동차를 운전했어도 자배법상 운행자라면 고의·중과실 여부와 관계없이 운행자책임을 진다. 이 경우 자배법이 국가배상법보다 우선한다.", "pages": [158, 159], "sourceHash": "95331e42102226df09b6a1a70959416292c39f0d3e0e3e206579fb3d544e3a4e"}], "민법4_강의자료(불법행위)-300": [{"key": "302", "start": 0, "end": 2, "citation": "대법원 2009. 10. 15. 선고 2009다42703,42710 판결", "summary": "업소의 일상적인 주차대행에 차와 열쇠를 맡기면 보통 보유자의 운행지배가 떠난다. 다만 친교 목적의 호의적 보관이나 우발적 대행 등 운행지배·이익이 남는 특별한 사정이 있으면 다르다.", "pages": [159], "sourceHash": "b4f681d7a43b1eb03861250006b0d595cd5754f8e07d9ae086d2839e8155c95c"}], "민법4_강의자료(불법행위)-301": [{"key": "303", "start": 0, "end": 1, "citation": "대법원 1987. 1. 20, 86다카1807 판결", "summary": "축의금 대신 차량과 운전수를 제공했다면 특별한 사정이 없는 한 보유자에게 운행지배·이익이 남는다. 단순히 이용한 혼주를 운행자나 승낙피보험자로 볼 수 없다.", "pages": [159], "sourceHash": "1c5bd4ff51d102e9b2ff0c19fe4404c70dad2ec636e1a9eb57230b4765a397cf"}], "민법4_강의자료(불법행위)-302": [{"key": "304", "start": 0, "end": 2, "citation": "대법원 1987. 11. 10, 87다카376 판결", "summary": "친구·가족 등 밀접한 사람에게 차량을 무상 대여해도 보통 소유자의 운행지배·이익은 남는다. 차주의 음주를 동승자가 알았다는 사정만으로 달라지지 않는다.", "pages": [159, 160], "sourceHash": "c2e5cd4e532766964d5ac437c6675e23656b397a594978e2ea485f69864c8ce3"}], "민법4_강의자료(불법행위)-303": [{"key": "305", "start": 0, "end": 2, "citation": "대법원 1998. 10. 27, 98다36382 판결", "summary": "농촌의 호의적인 협동작업 관계만으로 다른 사람의 차량에 대한 운행지배가 생기지는 않는다. 구체적 지배가능성이 없었던 이 사건 협력자의 운행자성을 부정했다.", "pages": [160], "sourceHash": "481c64de05a3e0bfe144e90c3850479f8941fcaf24c63da0935487513757ce13"}], "민법4_강의자료(불법행위)-304": [{"key": "306", "start": 0, "end": 3, "citation": "대법원 2002. 11. 26. 선고 2002다47181 판결", "summary": "차량과 이전서류를 넘겨 전문업자에게 매각을 맡긴 경우의 운행지배는 실제 인도·위탁관계 등을 보아야 한다. 이 사건에서는 원소유자와 중간 수탁자의 사용자의 운행지배를 부정했다.", "pages": [160], "sourceHash": "eb4d6cdf52dba37b7c99cbfaae613ab5da0a616256d3ab10b8af36da8aa1ad60"}], "민법4_강의자료(불법행위)-305": [{"key": "307", "start": 0, "end": 3, "citation": "대판 1996. 7. 26, 96다13194", "summary": "피용자의 무단운행이라도 업무와 밀접하거나 소유자의 사후 승낙을 배제할 수 없는 사정이 있다면, 소유자가 운행지배·이익을 완전히 잃었다고 단정할 수 없다.", "pages": [160], "sourceHash": "83c101ad5de35ee5ab9af5c1013a6a9083da7d0876b0b78cf8302388c61276a8"}], "민법4_강의자료(불법행위)-306": [{"key": "308", "start": 0, "end": 1, "citation": "대판 1998. 6. 23, 98다10380 판결", "summary": "절도운전에서는 원칙적으로 보유자의 운행지배·이익이 상실된다. 다만 관리상 중과실이 절도를 용인한 정도이고 사고 경위상 지배가 남는 예외적인 경우에는 운행자성이 인정될 수 있다.", "pages": [160], "sourceHash": "574bba807dd4d54abfc3aedf7bff5992277b4f56847a5af279cb39a848571636"}], "민법4_강의자료(불법행위)-307": [{"key": "309", "start": 0, "end": 2, "citation": "대법원 2001. 4. 24. 선고 2001다3788 판결", "summary": "차량을 절취당한 보유자에게 운행자성이 항상 남는 것은 아니다. 이 사건에서는 운행자성과 별도의 민법상 관리과실 책임을 모두 부정했다.", "pages": [160, 161], "sourceHash": "eac07dad0b83d939243b4ffe03b8eb7a4e15cfdd5543f60cef17cbd0da9fe47c"}], "민법4_강의자료(불법행위)-308": [{"key": "310", "start": 0, "end": 3, "citation": "대법원 2001. 1. 19. 선고 2000다12532 판결", "summary": "학원의 교습용 차량을 빌려 연습하는 수강생도 제3자에 대한 운행자책임을 질 수 있다. 과실은 그 연습경험 등 구체적 상황의 평균인을 기준으로 판단한다.", "pages": [161], "sourceHash": "dea21092d54966b150e5372789196740bda4ba5d31c1fe7bdc5de8d6a15baccb"}], "민법4_강의자료(불법행위)-309": [{"key": "311", "start": 0, "end": 2, "citation": "대법원 2002. 12. 10. 선고 2002다53193 판결", "summary": "수리를 맡겨 인도한 차량은 원칙적으로 수리업자가 운행을 지배한다. 다만 시운전과 함께 소유자의 별도 용무를 수행하는 등 특별한 사정이 있으면 공동운행도 인정될 수 있다.", "pages": [161], "sourceHash": "dab5b17332ee56d706c61e8a5bf5bab138a6840abc0fc9e2aceb710520d92aed"}], "민법4_강의자료(불법행위)-310": [{"key": "312", "start": 0, "end": 2, "citation": "대판 1988. 10. 25, 86다카2516 판결", "summary": "호텔 나이트클럽의 주차요원에게 맡긴 차량을 요원이 무단 운전해 사고를 냈다면, 보관을 맡긴 회사의 운행지배가 떠났다고 보아 운행자책임을 부정할 수 있다.", "pages": [161], "sourceHash": "f7d41af4a9f355641409ac2c090d77e8990c53e979c091ddcb25bfa3c43c877a"}], "민법4_강의자료(불법행위)-311": [{"key": "313", "start": 0, "end": 3, "citation": "대판 1994. 9. 23, 94다9085 판결", "summary": "피용자와 친구들의 무모한 사적 음주운전이 회사 운행의 범위를 완전히 벗어난 경우, 그 사정을 함께한 동승자에 대한 관계에서는 회사의 운행지배·이익을 부정할 수 있다.", "pages": [161, 162], "sourceHash": "bf11bb18523df82ee160004da8304459030cb631f93dd602d5ec54dfc69d8211"}], "민법4_강의자료(불법행위)-313": [{"key": "314", "start": 0, "end": 3, "citation": "대법원 2001. 11. 30, 2000다66393 판결", "summary": "자기 용무로 배우자의 차를 빌려 지인에게 운전시킨 동승자는 스스로 운행자에 해당할 수 있다. 이 사건에서는 차주에 대해 자배법상 ‘다른 사람’임을 주장할 수 없다고 보았다.", "pages": [162], "sourceHash": "2f2c80932f51813cd1f6138e53cfb7470691c320f396e28ad914c6d01e70a1e1"}], "민법4_강의자료(불법행위)-314": [{"key": "315", "start": 0, "end": 1, "citation": "대법원 1994. 8. 23. 선고 93다59595 판결", "summary": "운행 중 생긴 모든 사고가 자배법 책임 대상은 아니다. 정차한 버스에서 승객이 스스로 균형을 잃고 넘어진 이 사건은 운행으로 말미암은 사고가 아니라고 보았다.", "pages": [162], "sourceHash": "b4c8dc6d972855b8a8ded6b10d263cdc242f5ff784d7d348d1bebd955f0ce55b"}], "민법4_강의자료(불법행위)-315": [{"key": "316", "start": 0, "end": 3, "citation": "대법원 2005. 3. 25. 선고 2004다71232 판결", "summary": "경사지 주차에서 변속기·브레이크 등 안전조치를 하지 않아 차량이 굴러 사고가 나면 원칙적으로 운행에 따른 사고다. 전조등으로 작업하던 중 주차차량에 치인 경우도 포함된다.", "pages": [162, 163], "sourceHash": "f6ec048f4cf31ddf336683ce526bb43ca872d8d0031b68b1f8b4422b0c34bf08"}], "민법4_강의자료(불법행위)-316": [{"key": "317", "start": 0, "end": 2, "citation": "대법원 2004. 7. 9. 선고 2004다20340, 20357 판결", "summary": "구급차에 비치된 들것을 이용해 환자를 내리다 잘못 조작해 추락시킨 사고도 자동차 운행으로 인한 사고에 해당한다.", "pages": [163], "sourceHash": "d80a63a36d5e2da2dc31729f133ef9ed69e32259aaf55f46a1ff1b85c43b00fe"}], "민법4_강의자료(불법행위)-318": [{"key": "318", "start": 0, "end": 3, "citation": "대법원 2008. 2. 28. 선고 2006다18303 판결", "summary": "승객이 사고 후 버스에서 잠시 내려 갓길에 있었더라도 차량의 직접 위험범위에서 벗어나지 않았다면 자배법상 승객으로 보호된다.", "pages": [163], "sourceHash": "6edc896e394758b9c96796fb0ee43b518ce39baea16c09b36d5d97804cfa51e8"}], "민법4_강의자료(불법행위)-322": [{"key": "319", "start": 0, "end": 4, "citation": "대법원 2000. 2. 25. 선고 98다15934 판결", "summary": "제조업자는 기대 가능한 안전성·내구성을 갖춰야 한다. TV가 정상 사용 중 폭발했다면 내구연한을 다소 지났다는 이유만으로 결함책임이 배제되지 않는다.", "pages": [164, 165], "sourceHash": "678c9af3eabe9e32c6ad7615d776ea29268bfde1f098abf1f0b85cecda4b9059"}], "민법4_강의자료(불법행위)-325": [{"key": "320", "start": 0, "end": 2, "citation": "대법원 2013. 7. 12. 선고 2006다17539 판결", "summary": "제조물에는 불특정 다수에게 유통되는 제품뿐 아니라 특정 소비자와의 계약으로 직접 납품한 제품도 포함된다. 정부에 공급한 고엽제도 제조물에 해당한다.", "pages": [165, 166], "sourceHash": "e32ff5db4cb14e83edc5f42864bb0b80e63ad88b54a7344207dd74815b011477"}], "민법4_강의자료(불법행위)-326": [{"key": "321", "start": 0, "end": 1, "citation": "대법원 2013. 7. 12. 선고 2006다17539 판결", "summary": "효용은 거의 없고 반복 노출로 중대한 위해가 우려되며 사용자의 회피가 어려운 독성물질에는 제조업자의 고도 위험방지의무가 요구된다. 이를 어겨 유통하면 설계상 결함이 인정될 수 있다.", "pages": [166], "sourceHash": "e84e872c3b1c09c6a552d938884e996ae337f8fb1381d25214de1ff77b3c29f7"}], "민법4_강의자료(불법행위)-327": [{"key": "322", "start": 0, "end": 4, "citation": "대법원 2004. 3. 12. 선고 2003다16771 판결", "summary": "설계·표시 결함은 대체설계 가능성, 비용, 위험과 소비자의 회피 가능성 등을 종합해 판단한다. 정상 사용 중 제조자의 지배영역에서 통상 과실 없이 생기지 않을 사고가 났다면 결함·인과관계의 증명부담도 완화될 수 있다.", "pages": [166, 167], "sourceHash": "8e87c57f9c052afe0a5e3d88569c6542548892c6510ff065df0d2ba68b5319e9"}], "민법4_강의자료(불법행위)-328": [{"key": "323", "start": 0, "end": 2, "citation": "대법원 2008. 2. 28. 선고 2007다52287 판결", "summary": "의약품 설계결함은 제조·공급 당시의 기술수준·연구결과·경제성 등을 고려해 판단한다. 이 사건 감기약의 출혈성 뇌졸중 사망에는 배상책임을 지울 정도의 설계결함을 인정하지 않았다.", "pages": [167], "sourceHash": "e5830bfa2e5c25a8891de4e41fd59ee4112975cabb32dee5d20a1460954895c5"}], "민법4_강의자료(불법행위)-329": [{"key": "324", "start": 0, "end": 3, "citation": "대법원 2014. 4. 10. 선고 2011다22092 판결", "summary": "담배의 본질적 특성과 소비자 인식 등을 고려해 설계결함을 부정했다. 위험이 널리 알려지고 법정 경고도 표시했다면 추가 경고를 하지 않았다고 표시결함이 인정되지는 않는다.", "pages": [167], "sourceHash": "9860093464ab8e0be3a7168c994e6b0d6ee121d5d70df18fbae17606b418ea25"}], "민법4_강의자료(불법행위)-334": [{"key": "325", "start": 0, "end": 1, "citation": "대법원 2000. 2. 25. 선고 98다15934 판결", "summary": "정상 사용 중 발생한 사고가 제조업자의 배타적 지배영역에서 생겼고 과실 없이는 통상 발생하지 않는다는 점을 소비자가 증명하면, 제조업자가 다른 원인을 반증하지 못하는 한 결함과 인과관계를 추정한다.", "pages": [169], "sourceHash": "91e56299ecb25749e73638063935997fef6ce0c0a2a5e25a2ebf0477eb6d0b9b"}], "민법4_강의자료(불법행위)-338": [{"key": "326", "start": 0, "end": 3, "citation": "대법원 2013. 7. 12. 선고 2006다17539 판결", "summary": "정부의 제조지시를 따랐어도 결함이 있으면 제조물책임을 진다. 고엽제의 독성물질에 고도 위험방지의무를 인정하고, 일부 참전군인의 염소성여드름과 노출 사이의 인과관계도 인정했다.", "pages": [170], "sourceHash": "42141020a0909d70b5df0b3f47ae83368d759838e898cfca345d8932d00da813"}]}, "summaryCount": 336};
